window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbj-001',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-02T09:25:00',views:470,tags:['doorlopend krediet','hypotheektoets','BKR'],beste:'vbj-001-a1',
  titel:'Hoe gaan jullie om met een doorlopend krediet met saldo nul in de hypotheektoets?',
  body:`Een klant heeft een doorlopend krediet met een flinke limiet, maar er staat al jaren niets op. Op het BKR-overzicht staat het krediet gewoon als lopend. De klant vindt het onzin dat dit meetelt. Moet ik de limiet echt meenemen in de maximale hypotheek?`,
  antwoorden:[
   {id:'vbj-001-a1',auteur:'u1',datum:'2025-10-03T01:17:00',rA:{},rAdv:{},body:`Ja, in de toets telt de kredietlimiet, niet het actuele saldo. Zolang het krediet openstaat kan de klant er immers op elk moment over beschikken. De oplossing is om het krediet te laten opheffen voordat de aanvraag definitief wordt beoordeeld.
- Laat de klant schriftelijk opzeggen bij de kredietverstrekker.
- Vraag een bevestiging van beëindiging en een nieuw BKR-overzicht.
- Leg in het dossier vast dat het krediet is beëindigd en op welke datum.
Controleer de voorwaarden van de geldverstrekker: sommigen accepteren een opzegbevestiging, anderen willen de afmelding op het BKR-overzicht zien.`},
   {id:'vbj-001-a2',auteur:'u4',datum:'2025-10-04T06:23:00',rA:{u5:5},rAdv:{u6:5,u8:5},body:`Aanvulling: verlagen van de limiet kan ook, als de klant het krediet om een goede reden wil aanhouden. Bespreek dan wel wat dat kost aan leencapaciteit. Ik reken beide scenario's door en laat de klant kiezen, met de afweging in het adviesrapport.`}
  ]},
 {id:'vbj-002',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-05T20:50:00',views:580,tags:['studieschuld','DUO','hypotheektoets'],beste:'vbj-002-a1',
  titel:'Studieschuld in de aanloopfase: welke maandlast neem je mee?',
  body:`Een starter is net afgestudeerd en hoeft nog niet terug te betalen aan DUO. Er is dus nog geen maandbedrag vastgesteld. Hoe bepalen jullie welke last je meeneemt in de toets?`,
  antwoorden:[
   {id:'vbj-002-a1',auteur:'u5',datum:'2025-10-06T04:54:00',rA:{u1:4},rAdv:{u4:3},body:`Ook als de terugbetaling nog niet is gestart, telt de studieschuld mee. Je moet dan zelf een maandlast bepalen volgens de systematiek uit de actuele leennormen, op basis van de hoogte van de schuld, het terugbetaalstelsel en de rente.
- Vraag een recent overzicht uit Mijn DUO op met hoofdsom, rente en stelsel.
- Reken de maandlast uit zoals de normen voorschrijven en leg de berekening vast.
- Check of de geldverstrekker een eigen rekentool of vaste werkwijze hanteert.
Bespreek met de klant dat de echte DUO-maandlast later kan afwijken, en wat dat betekent voor het budget.`},
   {id:'vbj-002-a2',auteur:'u1',datum:'2025-10-06T19:06:00',rA:{u2:3,u8:4},rAdv:{},body:`Ons adviespakket rekent het mee zodra je de studieschuld met stelsel en rente invoert. Controleer wel of het juiste stelsel is gekozen, want dat maakt fors verschil in de uitkomst. Ik bewaar de DUO-schermafdruk altijd in het dossier.`}
  ]},
 {id:'vbj-003',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-09T09:55:00',views:529,tags:['BKR','herstelmelding','telefoon'],beste:'vbj-003-a1',
  titel:'Herstelde achterstand op een telefoonabonnement: probleem voor de aanvraag?',
  body:`Op het BKR-overzicht van een klant staat een toestelkrediet bij een telecomaanbieder met een achterstandsmelding die inmiddels als hersteld staat geregistreerd. De klant was hier zelf niet eens van op de hoogte. Hoe zwaar wegen geldverstrekkers zoiets?`,
  antwoorden:[
   {id:'vbj-003-a1',auteur:'u4',datum:'2025-10-09T17:17:00',rA:{},rAdv:{u1:5},body:`Dat verschilt per geldverstrekker en hangt af van de hoogte, de duur van de achterstand en hoe lang het herstel geleden is. Een kleine achterstand op een toestelkrediet die al geruime tijd is hersteld, wordt vaak met een goede verklaring geaccepteerd, maar er is geen garantie.
- Laat de klant een schriftelijke toelichting geven: wat er gebeurde en waarom.
- Vraag bij de telecomaanbieder een betalingshistorie of bevestiging van de afwikkeling op.
- Leg vooraf contact met de acceptant en noteer de reactie in het dossier.
Controleer altijd het acceptatiebeleid van de geldverstrekker voordat je de klant iets toezegt.`},
   {id:'vbj-003-a2',auteur:'u8',datum:'2025-10-09T20:29:00',rA:{u2:5},rAdv:{u2:3,u3:4,u6:5,u7:5},body:`Belangrijk voor je dossier: bespreek het BKR-overzicht expliciet met de klant en leg vast dat de klant het heeft gezien. Dat voorkomt verrassingen als de geldverstrekker de registratie later zelf aantreft.`}
  ]},
 {id:'vbj-004',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-14T20:30:00',views:509,tags:['private lease','BKR','maximale hypotheek'],beste:null,
  titel:'Private lease in de maximale hypotheek: hoe rekenen geldverstrekkers dat mee?',
  body:`Een stel heeft samen een private lease auto. Ik zie dat het contract op het BKR-overzicht staat. Rekenen geldverstrekkers de volledige leasetermijn mee, of een deel daarvan?`,
  antwoorden:[
   {id:'vbj-004-a1',auteur:'u1',datum:'2025-10-15T06:32:00',rA:{u3:4,u6:5,u7:4},rAdv:{},body:`Private lease contracten worden al enkele jaren bij BKR geregistreerd en geldverstrekkers nemen ze mee in de toets. Hoe precies verschilt: de ene rekent met de volledige maandtermijn, de andere met een vastgestelde omrekening.
- Vraag het leasecontract op met looptijd en maandtermijn.
- Kijk in de acceptatievoorwaarden van de beoogde geldverstrekker hoe lease meetelt.
- Leg vast welke last je hebt meegenomen en waarom.
Bespreek ook wat er gebeurt bij vroegtijdig beëindigen van het contract, want daar zitten vaak forse kosten aan.`},
   {id:'vbj-004-a2',auteur:'u2',datum:'2025-10-15T12:46:00',rA:{},rAdv:{u1:3,u3:3,u4:4,u7:4},body:`Vanuit planning: neem de leasekosten ook mee in het budgetoverzicht, los van de toets. Klanten zien lease vaak als vaste last die er nu eenmaal is, maar bij een hypotheek op het maximum blijft er weinig ruimte over.`}
  ]},
 {id:'vbj-005',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-17T21:10:00',views:342,tags:['oversluiten','consumptief krediet','box 3'],beste:'vbj-005-a1',
  titel:'Consumptief krediet aflossen uit de hypotheek bij oversluiten',
  body:`Een klant wil bij het oversluiten van de hypotheek een persoonlijke lening meefinancieren om lagere maandlasten te krijgen. De overwaarde is ruim voldoende. Waar moet ik op letten en wat leg ik vast?`,
  antwoorden:[
   {id:'vbj-005-a1',auteur:'u5',datum:'2025-10-18T11:20:00',rA:{u1:5,u6:5,u8:5},rAdv:{u2:5},body:`Fiscaal is dit deel geen eigenwoningschuld, want het geld wordt niet besteed aan de eigen woning. De rente is dus niet aftrekbaar en het leningdeel valt in box 3.
- Maak een apart leningdeel en leg de fiscale status vast.
- Laat zien wat de totale rentelast is over de looptijd ten opzichte van de huidige lening: een kortere schuld uitsmeren over dertig jaar kan uiteindelijk duurder zijn.
- Controleer of de geldverstrekker deze bestedingsdoelen accepteert en tot welke grens.
Leg in het advies vast waarom deze oplossing passend is en welke alternatieven je hebt besproken.`},
   {id:'vbj-005-a2',auteur:'u2',datum:'2025-10-19T00:47:00',rA:{u1:3,u8:5},rAdv:{u3:5,u4:5,u7:3,u8:5},body:`Ik adviseer in dit soort gevallen vaak een kortere looptijd voor het box 3-deel, zodat de klant de schuld in een vergelijkbaar tempo aflost als bij de persoonlijke lening. Dan haal je het voordeel van een lagere rente zonder dat de schuld veel langer blijft staan.`}
  ]},
 {id:'vbj-006',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-21T09:45:00',views:257,tags:['Wft','consumptief krediet','vakbekwaamheid'],beste:'vbj-006-a1',
  titel:'Mag ik als hypotheekadviseur ook adviseren over een persoonlijke lening?',
  body:`Een hypotheekklant vraagt of ik hem ook kan helpen met een persoonlijke lening voor een verbouwing van de keuken. Ons kantoor heeft vooral hypotheken als specialisme. Welke vergunning en diplomas heb ik daarvoor nodig?`,
  antwoorden:[
   {id:'vbj-006-a1',auteur:'u8',datum:'2025-10-22T06:13:00',rA:{u3:4},rAdv:{},body:`Adviseren over en bemiddelen in consumptief krediet is een aparte vergunningsactiviteit onder de Wft. Controleer eerst of jullie kantoorvergunning het product consumptief krediet omvat.
- Daarnaast moet de adviseur beschikken over het passende Wft-diploma voor consumptief krediet en dit actueel houden via PE.
- Je hebt een samenwerkingsovereenkomst met de kredietverstrekker nodig.
- Je zorgplicht geldt volledig: inventarisatie, kredietwaardigheidstoets en vastlegging.
Ontbreekt de vergunning of het diploma, verwijs de klant dan door en leg dat ook vast.`},
   {id:'vbj-006-a2',auteur:'u4',datum:'2025-10-22T19:00:00',rA:{u3:5},rAdv:{u3:5},body:`Wij hebben bewust gekozen om het niet te doen en werken samen met een collega-kantoor. Bij een verbouwing kijk ik wel eerst of het via de hypotheek kan, want dan valt het vaak binnen ons eigen vakgebied en is de rente meestal fiscaal aftrekbaar als het om de eigen woning gaat.`}
  ]},
 {id:'vbj-007',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-22T20:25:00',views:359,tags:['schuldregeling','BKR','acceptatie'],beste:'vbj-007-a1',
  titel:'Klant heeft schuldregeling achter de rug: wanneer weer kansrijk?',
  body:`Een klant heeft een minnelijke schuldregeling succesvol afgerond. Op het BKR-overzicht staat een registratie van de schuldregeling. Hij wil graag een woning kopen. Hoe kijken geldverstrekkers hiernaar en wat kan ik nu al doen?`,
  antwoorden:[
   {id:'vbj-007-a1',auteur:'u1',datum:'2025-10-23T12:53:00',rA:{u5:5},rAdv:{u4:4},body:`Een schuldregeling blijft na afronding nog een periode zichtbaar bij BKR, conform de geldende bewaartermijn. Zolang die registratie er staat, is een hypotheek bij de meeste geldverstrekkers lastig tot onmogelijk.
- Vraag de klant om de einddatum van de registratie op het overzicht te controleren.
- Bespreek de periode tot dan als voorbereiding: sparen, geen nieuwe kredieten.
- Leg het oriëntatiegesprek vast, inclusief je inschatting dat aanvragen nu weinig kans heeft.
Controleer wel periodiek het acceptatiebeleid, want dit kan wijzigen.`},
   {id:'vbj-007-a2',auteur:'u2',datum:'2025-10-23T13:59:00',rA:{u3:5},rAdv:{u3:5,u5:4},body:`Ik zou deze klant ook een budgetcoach of financiële planning aanraden. Een woning kopen direct na een schuldregeling vraagt een stevige buffer. Dat versterkt later ook het verhaal richting de geldverstrekker.`}
  ]},
 {id:'vbj-008',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-28T16:40:00',views:535,tags:['creditcard','BKR','limiet'],beste:null,
  titel:'Creditcard met limiet maar nooit gebruikt',
  body:`Op het BKR-overzicht van een klant staat een creditcard met een limiet. De klant gebruikt de kaart niet en wist niet dat het als krediet geregistreerd stond. Telt dit net als een doorlopend krediet mee?`,
  antwoorden:[
   {id:'vbj-008-a1',auteur:'u4',datum:'2025-10-29T07:38:00',rA:{u1:5,u8:4},rAdv:{},body:`Ja, een creditcard met een geregistreerde kredietlimiet wordt in de toets behandeld als een doorlopend krediet. Het gebruik doet er dan niet toe, de limiet telt.
- Laat de klant de kaart opzeggen als hij hem niet nodig heeft.
- Vraag een bevestiging van beëindiging op.
- Leg vast dat de afmelding is aangevraagd en controleer later het BKR-overzicht.
Niet alle creditcards staan bij BKR, dus kijk goed welk type kaart het is.`}
  ]},
 {id:'vbj-009',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-01T12:05:00',views:231,tags:['BKR','dossier','actualiteit'],beste:'vbj-009-a1',
  titel:'BKR-overzicht klant: welke datum is acceptabel?',
  body:`Een klant stuurde bij de inventarisatie een BKR-overzicht mee. Inmiddels zijn we drie maanden verder en dienen we de aanvraag pas nu in. Moet ik een nieuw overzicht opvragen?`,
  antwoorden:[
   {id:'vbj-009-a1',auteur:'u8',datum:'2025-11-02T01:47:00',rA:{u3:4,u4:4,u5:4},rAdv:{u7:4},body:`Zorg dat je advies is gebaseerd op actuele informatie. Een overzicht van een paar maanden oud kan inmiddels achterhaald zijn, bijvoorbeeld door een nieuw krediet of een lease-auto.
- Vraag vlak voor de aanvraag een nieuw overzicht op.
- Vraag de klant ook expliciet of er niet-geregistreerde verplichtingen zijn.
- Bewaar beide overzichten met datum in het dossier.
Controleer daarnaast de eisen van de geldverstrekker, want die hanteren soms een maximale ouderdom van stukken.`},
   {id:'vbj-009-a2',auteur:'u1',datum:'2025-11-03T00:07:00',rA:{u2:5,u4:4,u5:5,u7:5},rAdv:{u2:4},body:`Praktisch: het overzicht is gratis online op te vragen door de klant zelf. Ik stuur standaard een korte instructie mee. Dan is het binnen een kwartier geregeld.`}
  ]},
 {id:'vbj-010',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-05T14:15:00',views:414,tags:['studieschuld','draagkracht','DUO'],beste:'vbj-010-a1',
  titel:'Studieschuld met draagkrachtregeling: welke last telt?',
  body:`Een klant betaalt minder aan DUO vanwege de draagkrachtregeling. De verlaagde maandlast is veel lager dan het standaardbedrag. Mag ik met die lagere last rekenen in de toets?`,
  antwoorden:[
   {id:'vbj-010-a1',auteur:'u5',datum:'2025-11-05T22:08:00',rA:{u7:4},rAdv:{u1:4,u3:5,u8:4},body:`Een tijdelijk verlaagd bedrag door draagkracht is niet zonder meer het uitgangspunt in de toets. De actuele leennormen beschrijven hoe de maandlast van een studieschuld moet worden bepaald. Ga uit van die systematiek en niet van wat de klant op dit moment betaalt.
- Vraag het DUO-overzicht op met hoofdsom, rente en stelsel.
- Leg vast hoe je de maandlast hebt berekend en waarom.
- Bespreek met de klant dat de verlaging tijdelijk is.
Controleer daarnaast wat de geldverstrekker accepteert.`},
   {id:'vbj-010-a2',auteur:'u2',datum:'2025-11-06T18:15:00',rA:{u1:5,u6:3,u7:4,u8:5},rAdv:{},body:`In het budgetgesprek reken ik altijd met de volledige last die DUO zou vragen zonder verlaging. Een draagkrachtregeling kan namelijk wegvallen zodra het inkomen stijgt, en juist dat verwachten starters vaak.`}
  ]},
 {id:'vbj-011',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-08T13:05:00',views:224,tags:['ex-partner','BKR','echtscheiding'],beste:'vbj-011-a1',
  titel:'Krediet op naam van ex-partner nog niet afgelost',
  body:`Een gescheiden klant staat nog samen met de ex-partner geregistreerd op een persoonlijke lening. Volgens het convenant betaalt de ex de lening af. Telt deze lening mee in de toets voor de nieuwe woning?`,
  antwoorden:[
   {id:'vbj-011-a1',auteur:'u1',datum:'2025-11-09T04:20:00',rA:{u4:4,u6:4},rAdv:{u3:4,u7:3},body:`Zolang de klant hoofdelijk aansprakelijk is, telt de lening in principe mee. De afspraak in het convenant werkt alleen tussen de ex-partners, niet tegenover de kredietverstrekker.
- Kijk of de klant uit de hoofdelijkheid kan worden ontslagen; dat moet de kredietverstrekker goedkeuren.
- Lukt dat niet, bespreek dan aflossing of herfinanciering op naam van de ex.
- Leg het convenant en de stand van zaken vast in het dossier.
Sommige geldverstrekkers hebben een eigen beleid voor deze situatie, dus check dat vooraf.`},
   {id:'vbj-011-a2',auteur:'u4',datum:'2025-11-10T04:24:00',rA:{u7:4},rAdv:{u1:4},body:`Neem ook mee dat bij een achterstand van de ex de registratie bij beide partners terechtkomt. Dat risico wil je niet laten lopen als de klant net een hypotheek heeft. Uit de hoofdelijkheid laten ontslaan heeft dus ook voor later echt de voorkeur.`},
   {id:'vbj-011-a3',auteur:'u8',datum:'2025-11-10T13:48:00',rA:{u5:5},rAdv:{u1:5,u3:3,u4:5,u7:5},body:`Leg goed vast dat je dit risico hebt besproken, ook als de klant toch besluit het krediet te laten staan.`}
  ]},
 {id:'vbj-012',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-11T08:55:00',views:501,tags:['rood staan','betaalrekening','BKR'],beste:null,
  titel:'Rood staan op betaalrekening: zichtbaar in BKR en relevant?',
  body:`Een klant heeft een betaalrekening met een roodstandfaciliteit die hij regelmatig gebruikt. Wordt zoiets bij BKR geregistreerd en hoe gaan jullie ermee om?`,
  antwoorden:[
   {id:'vbj-012-a1',auteur:'u4',datum:'2025-11-11T19:20:00',rA:{u1:4,u2:4,u3:5},rAdv:{u3:4},body:`Een roodstandfaciliteit boven een bepaalde grens en looptijd wordt geregistreerd als doorlopend krediet. Is het geregistreerd, dan telt de limiet mee net als bij een ander doorlopend krediet. Ook als het niet geregistreerd is, zie je het vaak terug in de bankafschriften.
- Kijk in de afschriften of de klant structureel rood staat.
- Bespreek het patroon met de klant, want dat zegt iets over het budget.
- Leg vast hoe je het hebt meegewogen.
Een acceptant die structureel roodstand ziet, gaat daar ook vragen over stellen.`}
  ]},
 {id:'vbj-013',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-15T19:35:00',views:54,tags:['BKR','privacy','inventarisatie'],beste:'vbj-013-a1',
  titel:'Klant wil niet dat ik naar zijn BKR kijk',
  body:`Een klant weigert een BKR-overzicht te overleggen. Hij zegt dat de geldverstrekker het zelf toch controleert. Kan ik het advies dan wel geven?`,
  antwoorden:[
   {id:'vbj-013-a1',auteur:'u8',datum:'2025-11-16T16:52:00',rA:{u2:3,u5:3,u7:4},rAdv:{u4:5},body:`Je hebt informatie over de financiële verplichtingen nodig om passend te adviseren. Zonder inzicht kun je niet goed beoordelen of de financiering verantwoord is.
- Leg uit waarom je het nodig hebt en dat je het vertrouwelijk behandelt.
- Weigert de klant nog steeds, leg dan vast dat het advies onder dit voorbehoud is gegeven of zie af van advies.
- Bedenk dat de geldverstrekker zelf BKR raadpleegt en verrassingen dan pas laat boven water komen.
Kies voor een duidelijke vastlegging, want bij een afwijzing of klacht wordt hiernaar gevraagd.`},
   {id:'vbj-013-a2',auteur:'u5',datum:'2025-11-17T01:07:00',rA:{u6:5,u8:3},rAdv:{u1:4,u3:3},body:`Meestal helpt het om uit te leggen dat een onverwachte registratie later betekent dat het hele traject vertraagt, inclusief taxatie en kosten. Daarmee overtuig ik de meeste klanten.`}
  ]},
 {id:'vbj-014',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-19T10:20:00',views:593,tags:['ondernemer','zakelijk krediet','BKR'],beste:null,
  titel:'Telt een zakelijk krediet op naam van de eenmanszaak mee?',
  body:`Een zzp-klant heeft een zakelijk krediet voor zijn eenmanszaak. Op het BKR-overzicht zie ik het niet staan, maar in de jaarstukken wel. Moet ik dit meenemen in de hypotheektoets?`,
  antwoorden:[
   {id:'vbj-014-a1',auteur:'u1',datum:'2025-11-20T08:17:00',rA:{u2:5},rAdv:{u3:3,u4:5,u7:5},body:`Bij een eenmanszaak is de ondernemer privé aansprakelijk voor de zakelijke schulden. Of het krediet als last in de toets meetelt, hangt af van de normen en het beleid van de geldverstrekker: vaak is de rentelast al in de winst verwerkt, wat in het inkomen terugkomt.
- Kijk in de jaarstukken hoe de rente en aflossing zijn verwerkt.
- Vraag de inkomensverklaring als die vereist is.
- Leg de afspraken van het krediet vast in het dossier.
Overleg met de acceptant bij twijfel.`},
   {id:'vbj-014-a2',auteur:'u2',datum:'2025-11-20T09:39:00',rA:{u5:3,u7:3},rAdv:{u4:4},body:`Let er ook op of het krediet zekerheden heeft, zoals een borgstelling of een pandrecht. Bij een privé borgstelling is er een extra risico dat in het advies een plek verdient.`}
  ]},
 {id:'vbj-015',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T07:05:00',views:258,tags:['borgstelling','BKR','ouders'],beste:'vbj-015-a1',
  titel:'Borgstelling voor lening van kind: hoe meenemen?',
  body:`Ouders staan borg voor een lening van hun zoon. Nu willen ze zelf hun hypotheek aanpassen. Wordt een borgstelling geregistreerd en weegt die mee?`,
  antwoorden:[
   {id:'vbj-015-a1',auteur:'u5',datum:'2025-11-21T12:31:00',rA:{},rAdv:{u1:4,u3:4,u4:5},body:`Een borgstelling staat niet altijd op het BKR-overzicht, maar het is wel een verplichting die je moet meewegen in je advies. De kans dat de borg wordt aangesproken, bepaalt het risico.
- Vraag de borgstellingsovereenkomst op: hoogte, looptijd en voorwaarden.
- Vraag of de geldverstrekker borgstellingen meeweegt en hoe.
- Leg vast dat je het risico met de ouders hebt besproken.
Het is verstandig dit ook mee te nemen in het budget, voor het geval de zoon niet betaalt.`}
  ]},
 {id:'vbj-016',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-26T14:25:00',views:243,tags:['achteraf betalen','inventarisatie','budget'],beste:'vbj-016-a1',
  titel:'Achteraf betalen bij webwinkels: moet ik daar naar vragen?',
  body:`Ik krijg steeds vaker klanten die veel aankopen achteraf betalen bij webwinkels. Dit staat meestal niet op het BKR-overzicht. Hoe nemen jullie dit mee in de inventarisatie?`,
  antwoorden:[
   {id:'vbj-016-a1',auteur:'u2',datum:'2025-11-27T16:41:00',rA:{u1:3,u6:5,u8:3},rAdv:{u7:5},body:`Ik vraag er standaard naar in het budgetgesprek en bekijk de bankafschriften. Veel achteraf betalen zie je terug aan terugkerende betalingen aan betaaldiensten. Het zegt iets over het bestedingspatroon, ook al is het geen geregistreerd krediet.
- Vraag welke openstaande bedragen er zijn.
- Bespreek of de klant dit structureel doet.
- Leg je bevindingen vast in de inventarisatie.
Regelgeving rond deze vorm van krediet is in ontwikkeling, dus houd de actuele regels in de gaten.`},
   {id:'vbj-016-a2',auteur:'u8',datum:'2025-11-28T19:49:00',rA:{u1:5,u2:5,u3:4,u7:5},rAdv:{},body:`Goed punt. Ook als het niet in de toets meetelt, hoort het bij je zorgplicht om het in beeld te brengen. Vermeld in het dossier dat je ernaar hebt gevraagd.`}
  ]},
 {id:'vbj-017',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-29T08:25:00',views:212,tags:['huurkoop','consumptief krediet','toets'],beste:null,
  titel:'Huurkoop van meubels: krediet of niet?',
  body:`Een klant heeft een bankstel op afbetaling gekocht via een woonwinkel. Het contract heet huurkoop. Is dit een krediet dat in de toets meetelt?`,
  antwoorden:[
   {id:'vbj-017-a1',auteur:'u4',datum:'2025-11-29T15:54:00',rA:{u7:4,u8:5},rAdv:{u2:5,u7:3},body:`Huurkoop wordt juridisch als een vorm van consumptief krediet gezien en wordt in de regel bij BKR geregistreerd. Het telt dan mee als aflopend krediet met de maandtermijn.
- Kijk op het BKR-overzicht of het is geregistreerd.
- Vraag het contract op voor de looptijd en de termijn.
- Overweeg met de klant om het af te lossen als de termijn zwaar drukt op de leencapaciteit.
Leg vast welke last je hebt meegenomen.`}
  ]},
 {id:'vbj-018',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-03T16:45:00',views:428,tags:['aflossen','persoonlijke lening','voorwaarden'],beste:'vbj-018-a1',
  titel:'Persoonlijke lening laten aflossen vlak voor passeren: wat vragen geldverstrekkers?',
  body:`We gaan een persoonlijke lening laten aflossen zodat de klant voldoende kan lenen. Moet dat al vóór de aanvraag zijn gebeurd, of kan het bij het passeren?`,
  antwoorden:[
   {id:'vbj-018-a1',auteur:'u1',datum:'2025-12-03T21:38:00',rA:{u2:4,u4:4},rAdv:{u5:4,u8:5},body:`Dat verschilt per geldverstrekker. Sommigen accepteren dat de lening bij passeren wordt afgelost via de notaris, anderen willen dat het vóór de aanvraag al is geregeld en zichtbaar op een nieuw overzicht.
- Check het beleid en neem de voorwaarde op in de offerte.
- Vraag de aflosnota op bij de kredietverstrekker.
- Leg vast hoe en wanneer de aflossing plaatsvindt.
Bij aflossing via de notaris moet de financieringsopzet hier wel ruimte voor hebben.`},
   {id:'vbj-018-a2',auteur:'u5',datum:'2025-12-04T17:50:00',rA:{u2:3,u4:4,u6:4,u7:4},rAdv:{u2:5,u6:5},body:`En vergeet niet: is de aflossing uit eigen geld, controleer dan of de buffer daarna nog voldoende is voor de kosten koper en onvoorziene uitgaven.`}
  ]},
 {id:'vbj-019',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-07T20:00:00',views:10,tags:['BKR','A-codering','acceptatie'],beste:'vbj-019-a1',
  titel:'Zijn er geldverstrekkers die een lopende A-codering accepteren?',
  body:`Een klant heeft een actuele achterstandsmelding die nog niet is ingelost. De klant wil eerst de hypotheek regelen en daarna de achterstand oplossen. Is dat realistisch?`,
  antwoorden:[
   {id:'vbj-019-a1',auteur:'u4',datum:'2025-12-08T03:48:00',rA:{u3:4},rAdv:{u6:3,u7:5},body:`Een lopende achterstand zonder herstel is bij vrijwel alle geldverstrekkers een reden voor afwijzing. De volgorde moet dus andersom: eerst de achterstand oplossen, dan aanvragen.
- Laat de klant met de kredietverstrekker een regeling treffen.
- Vraag na inlossing een bevestiging en kijk of de herstelmelding verwerkt is.
- Leg in het dossier vast dat je de klant hebt geadviseerd niet direct aan te vragen.
Daarna blijft acceptatie maatwerk en afhankelijk van het beleid van de geldverstrekker.`},
   {id:'vbj-019-a2',auteur:'u8',datum:'2025-12-09T04:01:00',rA:{u1:5,u3:3,u4:5,u5:4},rAdv:{u3:5,u4:4,u5:5},body:`Pas op met toezeggingen. Leg vast dat je geen garantie op acceptatie hebt gegeven.`}
  ]},
 {id:'vbj-020',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-09T14:35:00',views:343,tags:['studieschuld','schenking','aflossen'],beste:'vbj-020-a1',
  titel:'Ouders betalen studieschuld kind af: gevolgen voor de toets',
  body:`Ouders willen een deel van de studieschuld van hun dochter aflossen zodat zij meer kan lenen. Hoe gaan jullie daarmee om in het advies?`,
  antwoorden:[
   {id:'vbj-020-a1',auteur:'u2',datum:'2025-12-10T07:45:00',rA:{u5:5,u6:4,u7:4},rAdv:{u4:5,u6:3,u8:5},body:`Aflossen op de studieschuld verlaagt de schuld waarmee in de toets wordt gerekend. Of de maandlast in de toets direct daalt, hangt af van hoe DUO het nieuwe bedrag vaststelt en wat je in de toets moet aanhouden.
- Vraag na aflossing een nieuw DUO-overzicht op.
- Leg de schenking schriftelijk vast en kijk naar de fiscale regels voor schenkingen.
- Vergelijk het alternatief: de schenking inzetten als eigen geld in de woning.
Reken beide scenario's door voor de klant.`},
   {id:'vbj-020-a2',auteur:'u5',datum:'2025-12-10T15:19:00',rA:{u2:4},rAdv:{},body:`Reken goed na wat het meest oplevert. Soms levert aflossen op de studieschuld meer leenruimte op dan het geld als eigen inbreng gebruiken, soms juist niet. Laat de cijfers spreken en leg de vergelijking vast.`}
  ]},
 {id:'vbj-021',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-14T15:05:00',views:465,tags:['krediet','overlijdensrisico','advies'],beste:'vbj-021-a1',
  titel:'Overlijdensrisicoverzekering bij een groot consumptief krediet',
  body:`Een stel neemt een groot consumptief krediet op voor een camper. Is het gangbaar om dan ook een overlijdensrisicoverzekering te adviseren?`,
  antwoorden:[
   {id:'vbj-021-a1',auteur:'u3',datum:'2025-12-15T01:09:00',rA:{},rAdv:{u2:5},body:`Het is goed om het risico te bespreken. Bij overlijden blijft de schuld staan voor de nabestaande. Of een aparte verzekering passend is, hangt af van de financiële situatie en de hoogte van het krediet.
- Breng in kaart hoe de nabestaande de lasten kan dragen.
- Kijk of bestaande verzekeringen het risico al dekken.
- Leg vast wat je hebt geadviseerd en wat de klant besloot.
Een kredietverzekering die bij de kredietverstrekker wordt aangeboden is niet altijd de beste keuze; vergelijk de dekking en kosten.`},
   {id:'vbj-021-a2',auteur:'u2',datum:'2025-12-15T12:25:00',rA:{u6:5},rAdv:{u7:5},body:`Bij een camper speelt ook de verkoopwaarde mee. Die daalt, maar is wel aanwezig. Neem dat mee in de afweging hoeveel dekking nodig is.`}
  ]},
 {id:'vbj-022',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-16T07:25:00',views:361,tags:['verduurzaming','persoonlijke lening','hypotheek'],beste:null,
  titel:'Persoonlijke lening voor verduurzaming via hypotheek of los?',
  body:`Een klant wil zonnepanelen en een warmtepomp laten plaatsen. Hij twijfelt tussen een persoonlijke lening en een verhoging van de hypotheek. Wat zijn jullie afwegingen?`,
  antwoorden:[
   {id:'vbj-022-a1',auteur:'u1',datum:'2025-12-18T07:25:00',rA:{u3:5,u6:5,u5:4},rAdv:{u3:5,u5:4},body:`Ik leg de volgende punten naast elkaar:
- Rente en fiscaal: een hypotheekverhoging heeft meestal een lagere rente, en kan onder voorwaarden tot de eigenwoningschuld behoren. Toets dat aan de actuele fiscale regels.
- Kosten: een verhoging brengt vaak kosten mee voor notaris, taxatie en advies. Bij een klein bedrag kan dat het rentevoordeel tenietdoen.
- Leenruimte: voor energiebesparende maatregelen is er vaak extra leenruimte. Controleer de actuele normen.
- Alternatieven: kijk naar de leningen van het Nationaal Warmtefonds en subsidies zoals de ISDE.
- Persoonlijke lening: snel geregeld, maar staat op het BKR-overzicht en beperkt een volgende hypotheek. De looptijd moet passen bij de levensduur van de installatie.
Maak een vergelijking van de totale kosten over de looptijd. Leg de alternatieven, de berekening en de keuze van de klant vast in het dossier.`}
  ]},
 {id:'vbj-023',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-21T12:35:00',views:595,tags:['BKR','bewaartermijn','registratie'],beste:null,
  titel:'Hoe lang blijft een registratie na aflossing zichtbaar?',
  body:`Een klant heeft vorig jaar een krediet volledig afgelost. Het krediet staat nog op het BKR-overzicht, met een einddatum. Hoe lang blijft dit zichtbaar en speelt het nog een rol?`,
  antwoorden:[
   {id:'vbj-023-a1',auteur:'u1',datum:'2025-12-22T06:53:00',rA:{u3:5,u4:5,u5:3,u7:4},rAdv:{u3:3,u6:5},body:`Na aflossing blijft een krediet nog een periode op het overzicht staan, conform de geldende bewaartermijn. Verwijs naar de actuele informatie van BKR, want de regels kunnen wijzigen. Een netjes afgelost krediet zonder bijzonderheden telt niet meer mee in de toets.
- Controleer of er een einddatum staat.
- Kijk of er geen bijzonderheidscodering bij staat.
- Leg vast dat het krediet is afgelost.
Is er wel een codering, dan is dat het punt waar de geldverstrekker naar kijkt.`}
  ]},
 {id:'vbj-024',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-23T07:15:00',views:305,tags:['integriteit','BKR','compliance'],beste:'vbj-024-a1',
  titel:'Mag ik de klant adviseren een krediet te verzwijgen?',
  body:`Een klant vraagt of hij een klein krediet dat niet bij BKR staat, gewoon kan weglaten bij de aanvraag. Hoe reageren jullie hierop?`,
  antwoorden:[
   {id:'vbj-024-a1',auteur:'u8',datum:'2025-12-24T06:55:00',rA:{u2:3,u3:4},rAdv:{u1:3,u5:3,u7:4},body:`Nee. Een adviseur mag nooit meewerken aan het achterhouden van informatie. Dat is in strijd met je zorgplicht en kan als fraude worden gezien.
- Leg de klant uit dat alle verplichtingen moeten worden opgegeven.
- Neem het krediet op in de inventarisatie en de aanvraag.
- Weigert de klant, beëindig dan het adviestraject en leg dat vast.
Bespreek het ook intern met compliance.`},
   {id:'vbj-024-a2',auteur:'u4',datum:'2025-12-24T17:52:00',rA:{u2:5,u7:5,u8:4},rAdv:{u1:3},body:`Zeg het gewoon eerlijk tegen de klant: als het later boven water komt, is de hypotheek zelfs in gevaar. Meestal is het dan snel opgelost.`}
  ]},
 {id:'vbj-025',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-27T11:10:00',views:372,tags:['doorlopend krediet','limiet','acceptatie'],beste:null,
  titel:'Kredietlimiet verlagen in plaats van opzeggen: accepteren geldverstrekkers dat?',
  body:`Een klant wil zijn doorlopend krediet niet opzeggen, omdat hij het als buffer wil houden voor noodgevallen. Hij is wel bereid de limiet flink te verlagen. Hoe snel is zo'n verlaging zichtbaar op het BKR-overzicht en accepteren geldverstrekkers een bevestiging van de kredietverstrekker?`,
  antwoorden:[
   {id:'vbj-025-a1',auteur:'u4',datum:'2025-12-28T08:10:00',rA:{u7:5,u8:5,u2:5,u6:5},rAdv:{u7:5,u2:5},body:`Een limietverlaging is meestal goed te regelen, maar let op de timing.
- De kredietverstrekker geeft de nieuwe limiet door aan BKR. Hoe snel dat gebeurt verschilt; reken op enkele dagen tot een paar weken. Vraag het na bij de kredietverstrekker.
- Geldverstrekkers rekenen met een vast deel van de limiet als maandlast, ook als er niets is opgenomen. Een lagere limiet levert dus direct leenruimte op.
- Veel geldverstrekkers accepteren een schriftelijke bevestiging van de kredietverstrekker met de nieuwe limiet en de ingangsdatum, sommige willen een bijgewerkt BKR-overzicht. Controleer het acceptatiebeleid.
Laat de klant de verlaging regelen voordat je de aanvraag indient. Bespreek ook dat een doorlopend krediet geen echte buffer is, want het blijft een schuld. Leg de bevestiging en het nieuwe BKR-overzicht vast in het dossier.`}
  ]},
 {id:'vbj-026',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-01T12:55:00',views:599,tags:['adviespakket','dossier','BKR'],beste:'vbj-026-a1',
  titel:'Hoe leggen jullie het BKR-overzicht vast in het adviespakket?',
  body:`Ik wil het BKR-overzicht van de klant netjes in het dossier opnemen en de kredieten in het adviespakket invoeren. Is er een vaste plek voor, of hangen jullie het gewoon als bijlage aan het dossier?`,
  antwoorden:[
   {id:'vbj-026-a1',auteur:'u6',datum:'2026-01-01T17:19:00',rA:{u4:5},rAdv:{u1:3,u4:3,u7:4},body:`Het handigst is beide te doen: de kredieten invoeren als verplichtingen bij de klant, en het overzicht zelf als document toevoegen.
- Voer per krediet het type, de limiet of hoofdsom, de maandlast en de einddatum in, zodat de berekening klopt.
- Upload het overzicht bij de documenten van de klant en geef het een herkenbare naam met datum.
- Zet bij een bijzonderheidscodering een notitie of taak, zodat een collega het ook ziet.
Let op dat je alleen bewaart wat je nodig hebt en volgens het bewaarbeleid van het kantoor.`},
   {id:'vbj-026-a2',auteur:'u8',datum:'2026-01-01T21:23:00',rA:{},rAdv:{u5:4,u6:5},body:`Vanuit de AVG: het BKR-overzicht bevat gevoelige gegevens. Sla het alleen op in het beveiligde dossier en niet in je mailbox. Zorg dat je bewaartermijnen in het privacybeleid staan.`}
  ]},
 {id:'vbj-027',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-05T14:50:00',views:517,tags:['private lease','adviespakket','invoer'],beste:null,
  titel:'Private lease invoeren in het adviespakket: als krediet of als vaste last?',
  body:`In het adviespakket kan ik kiezen tussen verschillende soorten verplichtingen. Ik weet niet zeker hoe ik private lease moet invoeren zodat de maximale hypotheek goed wordt berekend. Hoe doen jullie dat?`,
  antwoorden:[
   {id:'vbj-027-a1',auteur:'u6',datum:'2026-01-06T12:44:00',rA:{u5:5},rAdv:{u1:5,u5:5},body:`Kies het type verplichting dat de berekening laat rekenen zoals de geldverstrekker het doet. In de meeste pakketten is er een aparte optie voor lease of kun je het als aflopend krediet met maandlast invoeren.
- Vul de maandtermijn en de einddatum van het contract in.
- Controleer in de uitkomst of de last zichtbaar is in de toetsing.
- Vergelijk de uitkomst met de rekenwijze van de beoogde geldverstrekker.
Twijfel je, maak dan een notitie in het dossier met de gekozen invoer.`},
   {id:'vbj-027-a2',auteur:'u1',datum:'2026-01-07T16:30:00',rA:{},rAdv:{u3:3},body:`Ik maak er bij twijfel een tweede berekening bij waarin ik het anders invoer. Dan weet je de bandbreedte en kun je de klant eerlijk informeren.`}
  ]},
 {id:'vbj-028',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-06T21:00:00',views:238,tags:['leennormen','consumptief krediet','kredietwaardigheid'],beste:'vbj-028-a1',
  titel:'Leennormen voor consumptief krediet: welke normen hanteren jullie?',
  body:`Voor een hypotheek zijn de leennormen duidelijk. Bij een consumptief krediet zie ik wisselende werkwijzen. Welke normen gebruiken jullie bij het beoordelen van de kredietwaardigheid?`,
  antwoorden:[
   {id:'vbj-028-a1',auteur:'u2',datum:'2026-01-07T08:37:00',rA:{u3:5,u4:4,u5:3,u7:4},rAdv:{u7:4},body:`Bij consumptief krediet wordt de kredietwaardigheid getoetst volgens de leennormen uit de gedragscode van de branche, gebaseerd op een normbudget voor levensonderhoud. De kredietverstrekker voert de toets uit, maar als adviseur moet je zelf ook beoordelen of het krediet verantwoord is.
- Breng inkomen, woonlasten en overige lasten in kaart.
- Toets de maandlast aan de actuele normen.
- Leg vast hoe je tot het oordeel bent gekomen.
Gebruik de actuele versie van de normen, want die worden periodiek bijgewerkt.`},
   {id:'vbj-028-a2',auteur:'u8',datum:'2026-01-08T03:53:00',rA:{},rAdv:{u4:3,u5:4},body:`Belangrijk is dat het oordeel van de adviseur zelfstandig is. Alleen verwijzen naar een acceptatie door de kredietverstrekker is onvoldoende om je zorgplicht aan te tonen.`}
  ]},
 {id:'vbj-029',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-10T07:05:00',views:69,tags:['NHG','persoonlijke lening','toets'],beste:null,
  titel:'NHG-aanvraag met een lopende persoonlijke lening',
  body:`Een starter wil een woning kopen met NHG en heeft een persoonlijke lening die nog een paar jaar loopt. Gelden er bij NHG andere regels voor lopende kredieten dan zonder NHG?`,
  antwoorden:[
   {id:'vbj-029-a1',auteur:'u5',datum:'2026-01-10T23:10:00',rA:{},rAdv:{u2:3,u8:3},body:`NHG volgt in grote lijnen de wettelijke leennormen voor de toets van lasten, maar heeft eigen voorwaarden en normen. Lopende kredieten tellen mee in de berekening van de maximale lening.
- Check de actuele voorwaarden en normen van NHG.
- Bekijk of aflossen van de lening voordeliger uitpakt.
- Leg vast hoe je de last hebt meegenomen.
Bij een bijzonderheidscodering heeft NHG ook eigen regels; controleer die vooraf.`}
  ]},
 {id:'vbj-030',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-14T21:55:00',views:462,tags:['partner','BKR','aanvraag'],beste:'vbj-030-a1',
  titel:'BKR-registratie van een partner die niet meeleent',
  body:`Een klant koopt alleen een woning, maar woont samen met een partner die een negatieve BKR-registratie heeft. De partner komt niet op de hypotheek. Kijkt de geldverstrekker dan ook naar de partner?`,
  antwoorden:[
   {id:'vbj-030-a1',auteur:'u1',datum:'2026-01-15T11:22:00',rA:{u2:5,u3:5,u4:4,u6:3},rAdv:{u5:3,u7:4,u8:4},body:`Dat hangt af van de situatie en van het beleid van de geldverstrekker. Bij een gehuwd stel of geregistreerd partnerschap moet de partner vaak wel meetekenen, ook als hij of zij niet meeleent. Dan wordt de partner ook getoetst.
- Kijk naar de burgerlijke staat en het huwelijksgoederenregime.
- Vraag de voorwaarden op bij de geldverstrekker.
- Bespreek met de klant wat dit betekent.
Leg vast welke informatie je over de partner hebt ontvangen en hoe je die hebt meegewogen.`},
   {id:'vbj-030-a2',auteur:'u4',datum:'2026-01-16T05:22:00',rA:{u1:5,u5:5,u6:4,u8:3},rAdv:{u5:5,u7:5},body:`Bij ongehuwd samenwonen kijken geldverstrekkers meestal alleen naar de aanvrager. Toch is het verstandig om de lasten van de partner te bespreken in het budget, want in de praktijk betaal je samen.`}
  ]},
 {id:'vbj-031',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-18T12:05:00',views:213,tags:['financial lease','DGA','zakelijk'],beste:'vbj-031-a1',
  titel:'Financial lease auto op naam van de bv: gevolgen privé?',
  body:`Een DGA heeft een auto in financial lease via zijn bv. Hij staat zelf als borg. Telt dit mee in zijn persoonlijke hypotheektoets?`,
  antwoorden:[
   {id:'vbj-031-a1',auteur:'u5',datum:'2026-01-19T15:37:00',rA:{u6:3},rAdv:{u2:5,u3:5},body:`Een zakelijk leasecontract op naam van de bv staat in principe niet op het privé BKR-overzicht. Een persoonlijke borgstelling is wel een risico dat je moet meewegen.
- Vraag het leasecontract en de borgstelling op.
- Kijk hoe de geldverstrekker omgaat met borgstellingen van een DGA.
- Neem de inkomensbeoordeling van de DGA mee, want daar zit de lease al in de cijfers van de bv.
Leg vast welke afweging je hebt gemaakt.`},
   {id:'vbj-031-a2',auteur:'u2',datum:'2026-01-20T00:33:00',rA:{u4:5,u6:5},rAdv:{u1:3,u3:4,u5:4,u8:3},body:`Overweeg ook of de borgstelling bij de bv kan worden afgebouwd. Dat vermindert het privérisico voor de klant en daarmee ook voor zijn gezin.`}
  ]},
 {id:'vbj-032',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-21T20:40:00',views:202,tags:['gesprek','BKR','klantcontact'],beste:'vbj-032-a2',
  titel:'Hoe bespreek je een BKR-registratie zonder dat de klant zich schaamt?',
  body:`In het eerste gesprek merk ik dat klanten vaak niet eerlijk zijn over kredieten of achterstanden. Hoe pakken jullie dat gesprek aan zodat alles op tafel komt?`,
  antwoorden:[
   {id:'vbj-032-a1',auteur:'u4',datum:'2026-01-22T11:29:00',rA:{u7:5},rAdv:{u1:4,u2:3},body:`Ik leg vooraf uit dat ik het BKR-overzicht standaard bij iedere klant opvraag. Dan voelt niemand zich apart behandeld. Ik vertel ook dat een registratie geen eindpunt hoeft te zijn, maar dat ik het wel moet weten.
- Vraag open: hebben jullie ooit een betalingsachterstand gehad?
- Laat het overzicht samen doornemen.
- Leg de uitleg van de klant vast.`},
   {id:'vbj-032-a2',auteur:'u2',datum:'2026-01-22T22:37:00',rA:{u5:3,u7:3},rAdv:{u3:5,u4:3,u5:3,u6:3},body:`Bij mij werkt het goed om eerst het budget te bespreken voordat we het over kredieten hebben. Klanten zien dan zelf het verband en zijn eerder geneigd openheid te geven.`},
   {id:'vbj-032-a3',auteur:'u8',datum:'2026-01-23T00:50:00',rA:{u1:5,u3:5,u4:3,u6:4},rAdv:{u3:4,u5:4},body:`Mooie aanpak. Vergeet niet in het dossier vast te leggen dat de klant expliciet is gevraagd naar alle verplichtingen.`}
  ]},
 {id:'vbj-033',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-26T13:35:00',views:254,tags:['nieuw krediet','aanvraag','BKR'],beste:'vbj-033-a1',
  titel:'Kredietopname tijdens de hypotheekaanvraag',
  body:`Een klant heeft tussen offerte en passeren een nieuwe auto gekocht met een financiering via de dealer. Hij meldde het pas achteraf. Wat moet ik nu doen?`,
  antwoorden:[
   {id:'vbj-033-a1',auteur:'u1',datum:'2026-01-26T21:19:00',rA:{},rAdv:{u3:4,u4:3,u6:3,u7:4},body:`Dit moet je direct melden bij de geldverstrekker. De offerte is gebaseerd op de situatie bij de aanvraag en een nieuw krediet kan de toets veranderen.
- Vraag het nieuwe contract en een actueel BKR-overzicht op.
- Laat opnieuw rekenen of de financiering nog past.
- Leg alles vast, inclusief het moment waarop de klant het meldde.
In sommige gevallen moet de klant het krediet aflossen voordat het passeren door kan gaan.`},
   {id:'vbj-033-a2',auteur:'u8',datum:'2026-01-27T19:30:00',rA:{u3:5,u4:5,u5:5,u7:4},rAdv:{u1:4,u2:4,u4:3,u5:5},body:`Waarschuw klanten in het begin van het traject standaard om geen nieuwe kredieten af te sluiten tot het passeren. Zet dat ook in je opdrachtbevestiging.`}
  ]},
 {id:'vbj-034',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-28T16:45:00',views:279,tags:['schulden','betalingsachterstand','inventarisatie'],beste:null,
  titel:'Achterstand bij zorgverzekeraar of belastingdienst: geen BKR, wel relevant?',
  body:`Een klant heeft een betalingsregeling met de belastingdienst en een achterstand bij de zorgverzekeraar. Deze staan niet op het BKR-overzicht. Hoe weeg ik ze mee in het advies?`,
  antwoorden:[
   {id:'vbj-034-a1',auteur:'u2',datum:'2026-01-29T22:13:00',rA:{u7:5},rAdv:{u1:4,u3:5,u4:4,u8:5},body:`Ook schulden buiten BKR zijn relevant voor je advies. Ze drukken op het budget en zeggen iets over het betaalgedrag.
- Vraag een overzicht van alle openstaande schulden en betalingsregelingen.
- Neem de maandlast mee in het budget.
- Bespreek of het verstandig is eerst de schulden op te lossen.
Leg je overwegingen vast. Bij twijfel over de verantwoordheid van de lening heeft de klant meer aan advies over de schulden dan aan een hypotheek.`},
   {id:'vbj-034-a2',auteur:'u4',datum:'2026-01-30T23:57:00',rA:{u8:3},rAdv:{u1:5,u3:4,u6:5,u8:3},body:`Geldverstrekkers vragen soms ook naar betalingsregelingen in de aanvraag. Eerlijk opgeven is altijd beter dan later uitleggen.`}
  ]},
 {id:'vbj-035',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-01T07:10:00',views:443,tags:['eigen geld','persoonlijke lening','hypotheek'],beste:'vbj-035-a1',
  titel:'Klant wil krediet nemen voor de eigen inbreng',
  body:`Een klant wil de kosten koper betalen met een persoonlijke lening. Kan dat en hoe kijken geldverstrekkers ernaar?`,
  antwoorden:[
   {id:'vbj-035-a1',auteur:'u5',datum:'2026-02-02T09:50:00',rA:{u4:5,u6:4,u7:3},rAdv:{u2:4,u3:5,u4:4,u7:3},body:`Een lening voor de eigen inbreng gaat ten koste van de leencapaciteit, want de nieuwe last telt mee in de toets. Bovendien kijken geldverstrekkers naar de herkomst van eigen geld, en een recent krediet roept vragen op.
- Bespreek of de klant de kosten kan sparen of een schenking kan krijgen.
- Neem de last mee in de toets als de klant toch doorzet.
- Leg vast dat je de risico's hebt besproken.
Controleer altijd het beleid van de geldverstrekker over de herkomst van eigen middelen.`},
   {id:'vbj-035-a2',auteur:'u8',datum:'2026-02-03T09:42:00',rA:{u3:4,u4:5},rAdv:{u2:4,u3:5},body:`Vanuit verantwoord lenen: een krediet voor eigen geld is een signaal dat de klant mogelijk te krap zit. Leg goed vast waarom het advies toch passend is, als je ermee doorgaat.`}
  ]},
 {id:'vbj-036',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-04T15:40:00',views:369,tags:['studieschuld','aflossen','afweging'],beste:'vbj-036-a1',
  titel:'Studieschuld nog volledig, of eerst aflossen voor een hypotheek?',
  body:`Een klant heeft spaargeld en een studieschuld. Hij vraagt of hij het spaargeld beter in de studieschuld of in de woning kan stoppen. Welke afwegingen bespreken jullie?`,
  antwoorden:[
   {id:'vbj-036-a1',auteur:'u2',datum:'2026-02-05T18:13:00',rA:{u5:5,u7:5},rAdv:{u1:5,u3:3},body:`Het hangt af van de rente op de studieschuld, de leenruimte en de buffer. De studieschuld heeft vaak gunstige voorwaarden, maar weegt mee in de toets.
- Reken uit wat aflossen oplevert in leenruimte.
- Vergelijk met inbreng in de woning: lagere hypotheek, kosten koper.
- Houd voldoende buffer achter.
Leg de doorrekening vast en laat de klant de keuze maken.`},
   {id:'vbj-036-a2',auteur:'u5',datum:'2026-02-06T17:08:00',rA:{u4:5,u8:5},rAdv:{u2:4,u4:4,u7:4},body:`Let op dat geld dat in de studieschuld is gestopt, niet meer beschikbaar is als buffer. Bij een starter zou ik daar voorzichtig mee zijn.`},
   {id:'vbj-036-a3',auteur:'u1',datum:'2026-02-07T15:24:00',rA:{u2:3,u3:5,u8:5},rAdv:{u4:5,u5:3,u6:3,u8:5},body:`Ik laat in het advies standaard drie varianten zien: alles in de woning, alles in de studieschuld en een mix. Dat maakt het gesprek veel concreter.`}
  ]},
 {id:'vbj-037',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-10T15:05:00',views:244,tags:['buitenland','krediet','toets'],beste:null,
  titel:'Klant heeft een krediet bij een buitenlandse aanbieder',
  body:`Een klant die enige tijd in het buitenland heeft gewerkt, heeft daar nog een lening lopen. Deze staat niet op het Nederlandse BKR-overzicht. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbj-037-a1',auteur:'u4',datum:'2026-02-12T08:05:00',rA:{u8:5,u1:5,u7:5},rAdv:{u1:5,u7:5},body:`Een lening die niet op het BKR-overzicht staat, is nog steeds een verplichting en moet mee in de toetsing.
- Vraag de klant om het contract, een recent overzicht met het openstaande saldo en de maandlast, en betalingsbewijzen.
- Reken de maandlast om naar euro's en houd rekening met valutarisico.
- Controleer het acceptatiebeleid: sommige geldverstrekkers vragen ook een overzicht van een buitenlands kredietregister.
- Overweeg met de klant of aflossen voor de aanvraag verstandig is.
Wijs de klant op zijn plicht om alle verplichtingen te melden. Het verzwijgen van een lening bij een aanvraag kan als fraude worden aangemerkt, met gevolgen zoals registratie bij de geldverstrekker. Leg in het dossier vast welke lening er is, welke stukken je hebt gezien en hoe je hem in de toetsing hebt meegenomen.`}
  ]},
 {id:'vbj-038',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-12T13:55:00',views:447,tags:['aflopend krediet','einddatum','toets'],beste:null,
  titel:'Toetsing bij een krediet dat binnenkort afloopt',
  body:`Een klant heeft een persoonlijke lening die over een paar maanden is afgelost. Telt de volledige maandlast nog mee in de toets?`,
  antwoorden:[
   {id:'vbj-038-a1',auteur:'u4',datum:'2026-02-13T02:36:00',rA:{u3:3,u7:5,u8:3},rAdv:{u1:3,u3:5,u5:3,u6:5},body:`In principe telt een lopend krediet mee zolang het niet is afgelost. Sommige geldverstrekkers maken een uitzondering voor kredieten die op korte termijn aflopen, maar dat is beleid en geen regel.
- Kijk in de acceptatievoorwaarden of er een uitzondering geldt.
- Overweeg om het restant nu af te lossen.
- Leg de afweging vast.`}
  ]},
 {id:'vbj-039',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-16T11:55:00',views:467,tags:['dossier','compliance','afwijken'],beste:'vbj-039-a1',
  titel:'Vastlegging als klant een advies over krediet negeert',
  body:`Ik heb een klant geadviseerd zijn doorlopend krediet op te zeggen, maar hij wil dat niet. Daardoor kan hij minder lenen dan hij wil. Hoe leg ik dat vast?`,
  antwoorden:[
   {id:'vbj-039-a1',auteur:'u8',datum:'2026-02-16T19:43:00',rA:{u5:3},rAdv:{u1:5},body:`Leg in het adviesrapport vast wat je hebt geadviseerd, waarom, en wat de klant uiteindelijk besloot. Laat de klant dit ondertekenen of bevestigen.
- Beschrijf het effect op de leencapaciteit.
- Beschrijf welke alternatieven je hebt besproken.
- Bewaar de bevestiging in het dossier.
Zo kun je later aantonen dat de klant geïnformeerd heeft gekozen.`},
   {id:'vbj-039-a2',auteur:'u1',datum:'2026-02-17T04:30:00',rA:{u7:3},rAdv:{},body:`In ons adviespakket kun je een afwijkende klantkeuze vastleggen. Dat neem ik dan ook op in het rapport.`}
  ]},
 {id:'vbj-040',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-20T19:00:00',views:476,tags:['autofinanciering','BKR','dealer'],beste:null,
  titel:'Dealerfinanciering auto: altijd BKR?',
  body:`Een klant heeft zijn auto gefinancierd via de dealer, met een slottermijn. Ik zie het niet terug op het BKR-overzicht. Kan dat kloppen?`,
  antwoorden:[
   {id:'vbj-040-a1',auteur:'u1',datum:'2026-02-21T02:11:00',rA:{u3:4,u4:5,u5:4,u8:4},rAdv:{u5:4},body:`Een autofinanciering is in de regel een consumptief krediet dat bij BKR wordt geregistreerd. Staat het er niet op, dan kan het zijn dat het overzicht niet actueel is of dat het contract een andere vorm heeft.
- Vraag het financieringscontract op.
- Vraag bij twijfel een nieuw overzicht op.
- Neem de last mee in het advies, ook als het niet geregistreerd is.
Let bij een slottermijn op wat de klant aan het einde nog moet betalen.`},
   {id:'vbj-040-a2',auteur:'u4',datum:'2026-02-21T16:30:00',rA:{},rAdv:{u2:4},body:`Die slottermijn is het grootste risico. Klanten vergeten dat vaak. Neem het mee in het budget en bespreek hoe ze het willen betalen.`}
  ]},
 {id:'vbj-041',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-24T15:55:00',views:339,tags:['opzeggen','BKR','misverstand'],beste:'vbj-041-a1',
  titel:'Kredietopzegging en het effect op de kredietscore',
  body:`Een klant is bang dat het opzeggen van zijn creditcard een negatief effect heeft. Hij heeft gehoord dat je een goede kredietgeschiedenis moet opbouwen. Klopt dat in Nederland?`,
  antwoorden:[
   {id:'vbj-041-a1',auteur:'u4',datum:'2026-02-25T14:05:00',rA:{u1:4,u3:5,u6:4},rAdv:{u2:3,u3:4,u7:4,u8:5},body:`In Nederland werkt het anders dan in sommige andere landen. Er is geen kredietscore op basis van een positieve geschiedenis zoals elders. Het BKR-overzicht toont kredieten en eventuele achterstanden. Een opgezegd krediet zonder achterstand heeft geen negatief effect.
- Leg dat rustig uit aan de klant.
- Laat het opzeggen bevestigen.
- Leg vast dat je het hebt besproken.`},
   {id:'vbj-041-a2',auteur:'u2',datum:'2026-02-26T03:41:00',rA:{u5:4},rAdv:{u1:5,u8:3},body:`Dit misverstand hoor ik vaak bij expats. Een korte uitleg in het eerste gesprek voorkomt veel onrust.`}
  ]},
 {id:'vbj-042',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T20:55:00',views:411,tags:['verbouwing','box 1','hypotheek'],beste:'vbj-042-a1',
  titel:'Krediet voor een verbouwing via de hypotheek: wanneer box 1?',
  body:`Een klant wil een verbouwing financieren. Hij heeft al een offerte voor een persoonlijke lening. Ik denk dat het via de hypotheek kan. Wanneer is de rente aftrekbaar?`,
  antwoorden:[
   {id:'vbj-042-a1',auteur:'u5',datum:'2026-02-27T21:45:00',rA:{},rAdv:{u4:3,u6:5},body:`Als de lening wordt gebruikt voor verbetering of onderhoud van de eigen woning en aan de fiscale voorwaarden voldoet, kan het eigenwoningschuld zijn. Dan moet je ook letten op de aflossingseis en de bouwdepotregels.
- Vraag de verbouwingsspecificatie op.
- Controleer de fiscale voorwaarden voor eigenwoningschuld.
- Leg vast welke kosten in aanmerking komen.
Een persoonlijke lening voor dezelfde verbouwing levert geen aftrek op.`},
   {id:'vbj-042-a2',auteur:'u1',datum:'2026-02-28T22:26:00',rA:{u4:4,u7:5},rAdv:{u6:5},body:`Let ook op de bouwdepotvoorwaarden van de geldverstrekker: termijnen en welke kosten ze accepteren.`}
  ]},
 {id:'vbj-043',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-01T10:40:00',views:282,tags:['DGA','rekening courant','toets'],beste:null,
  titel:'Hoe toets je een rekening courant bij een DGA met eigen bv?',
  body:`Een DGA heeft een schuld in rekening courant aan zijn bv. Dit staat niet bij BKR. Hoe nemen jullie dit mee?`,
  antwoorden:[
   {id:'vbj-043-a1',auteur:'u5',datum:'2026-03-01T14:27:00',rA:{u1:3,u7:3},rAdv:{u6:4},body:`Een rekening-courantschuld aan de eigen bv is een privéschuld. Die is niet geregistreerd, maar wel relevant voor je advies en mogelijk voor de geldverstrekker.
- Vraag de jaarstukken en de rekening-courantovereenkomst op.
- Bespreek of en hoe de schuld wordt afgelost.
- Houd rekening met fiscale regels rond rekening-courantschulden.
Leg vast hoe je het hebt meegewogen.`},
   {id:'vbj-043-a2',auteur:'u2',datum:'2026-03-02T15:49:00',rA:{u5:5,u6:3},rAdv:{u3:4},body:`Bij een hoge rekening-courantschuld zou ik de klant adviseren eerst met zijn fiscalist te overleggen. Dit kan fiscale gevolgen hebben die het advies beïnvloeden.`}
  ]},
 {id:'vbj-044',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-06T13:45:00',views:447,tags:['BKR','correctie','klacht'],beste:'vbj-044-a1',
  titel:'BKR-registratie die volgens de klant onterecht is',
  body:`Een klant meent dat een achterstandsmelding onterecht is. Hij heeft volgens eigen zeggen altijd op tijd betaald. Wat kan hij doen?`,
  antwoorden:[
   {id:'vbj-044-a1',auteur:'u8',datum:'2026-03-06T20:21:00',rA:{u2:3,u7:4},rAdv:{u2:3,u4:5},body:`De klant moet eerst bij de kredietverstrekker die de registratie heeft gedaan om correctie of verwijdering vragen. Die partij is verantwoordelijk voor de juistheid. Komt de klant er niet uit, dan kan hij de klachtenprocedure van die partij volgen en daarna eventueel naar Kifid of de rechter.
- Laat de klant bewijzen verzamelen, zoals bankafschriften.
- Leg vast dat de registratie wordt betwist.
- Overleg met de geldverstrekker of de aanvraag kan wachten.`},
   {id:'vbj-044-a2',auteur:'u4',datum:'2026-03-06T22:16:00',rA:{u1:3,u3:3,u5:3,u7:5},rAdv:{u2:5,u3:4,u7:5},body:`In de praktijk duurt zoiets weken tot maanden. Bespreek met de klant of dit past in de planning van de woningaankoop.`}
  ]},
 {id:'vbj-045',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-09T18:05:00',views:505,tags:['studieschuld','partner','toets'],beste:null,
  titel:'Telt een studieschuld van de partner mee als die niet meeleent?',
  body:`Een klant koopt een woning alleen. Haar partner heeft een flinke studieschuld. Telt die schuld mee?`,
  antwoorden:[
   {id:'vbj-045-a1',auteur:'u1',datum:'2026-03-10T11:37:00',rA:{u4:3,u5:4},rAdv:{u2:4,u4:4,u8:5},body:`Als de partner niet meeleent en niet meetekent, telt de studieschuld van de partner meestal niet mee. Dat hangt wel af van de burgerlijke staat en het beleid van de geldverstrekker.
- Controleer of de partner moet meetekenen.
- Bespreek de gezamenlijke lasten in het budget.
- Leg je afweging vast.`}
  ]},
 {id:'vbj-046',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-14T10:00:00',views:157,tags:['kredietverzekering','advies','persoonlijke lening'],beste:'vbj-046-a1',
  titel:'Kredietverzekering bij persoonlijke lening: advies nodig?',
  body:`Bij het afsluiten van een persoonlijke lening krijgt de klant een kredietverzekering aangeboden. Moet ik daar ook over adviseren?`,
  antwoorden:[
   {id:'vbj-046-a1',auteur:'u3',datum:'2026-03-14T23:24:00',rA:{u1:5,u8:5},rAdv:{u1:3,u6:3,u8:5},body:`Als je adviseert over het krediet, hoort het risico bij overlijden, arbeidsongeschiktheid en werkloosheid erbij. Of een kredietverzekering passend is, hangt af van de situatie en bestaande dekking.
- Vergelijk de dekking met wat de klant al heeft.
- Let op uitsluitingen en wachttijden.
- Leg vast wat je hebt geadviseerd.
Een aparte verzekering is vaak niet nodig als bestaande dekking voldoende is.`},
   {id:'vbj-046-a2',auteur:'u8',datum:'2026-03-15T09:39:00',rA:{u3:3,u6:3},rAdv:{u6:5},body:`Adviseer je over de verzekering, dan heb je daarvoor ook de juiste vergunning en vakbekwaamheid nodig. Check dat even.`}
  ]},
 {id:'vbj-047',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-17T17:35:00',views:318,tags:['oversluiten','consumptief krediet','samenvoegen'],beste:'vbj-047-a1',
  titel:'Klant heeft drie kleine kredieten: samenvoegen?',
  body:`Een klant heeft drie kleine leningen. Hij vraagt of samenvoegen tot één lening voordeliger is. Wat zijn jullie aandachtspunten?`,
  antwoorden:[
   {id:'vbj-047-a1',auteur:'u2',datum:'2026-03-18T12:58:00',rA:{u4:3,u5:4,u6:3},rAdv:{u5:4},body:`Samenvoegen kan voordelig zijn als de nieuwe rente lager is, maar let op de looptijd en eventuele kosten.
- Vergelijk totale kosten over de looptijd.
- Kijk naar een eventuele vergoeding voor vervroegd aflossen.
- Check of de nieuwe lening in de toets beter uitpakt.
Leg de vergelijking vast en bespreek met de klant waarom er drie leningen zijn ontstaan.`},
   {id:'vbj-047-a2',auteur:'u4',datum:'2026-03-19T07:56:00',rA:{u1:5,u2:3,u5:3,u6:4},rAdv:{u2:5,u3:3,u5:3},body:`Bespreek ook of de oude leningen echt worden opgezegd. Anders staat de klant straks met meer kredietruimte dan voorheen.`}
  ]},
 {id:'vbj-048',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-21T17:10:00',views:480,tags:['adviesrapport','BKR','vastlegging'],beste:null,
  titel:'Wat zet ik in het adviesrapport over de BKR-toetsing?',
  body:`Ik twijfel hoe uitgebreid ik de BKR-toetsing in het rapport moet beschrijven. Is het genoeg om te vermelden dat er geen bijzonderheden waren?`,
  antwoorden:[
   {id:'vbj-048-a1',auteur:'u8',datum:'2026-03-22T07:47:00',rA:{u1:3,u2:3},rAdv:{u1:4,u4:3},body:`Vermeld in elk geval de datum van het overzicht, welke kredieten erop stonden en hoe je ze hebt meegenomen in de berekening. Bij bijzonderheden beschrijf je wat je hebt gedaan.
- Datum en bron van het overzicht.
- Overzicht van de kredieten en de gebruikte maandlasten.
- Eventuele bijzonderheden en toelichting.
Zo is het advies voor een buitenstaander na te volgen.`}
  ]},
 {id:'vbj-049',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-25T15:40:00',views:264,tags:['WSNP','schuldsanering','acceptatie'],beste:null,
  titel:'Acceptatie na een WSNP-traject',
  body:`Een klant heeft een wettelijk schuldsaneringstraject afgerond en een schone lei gekregen. Hij wil een woning kopen. Is dat haalbaar?`,
  antwoorden:[
   {id:'vbj-049-a1',auteur:'u4',datum:'2026-03-26T22:40:00',rA:{u1:5,u7:4},rAdv:{u1:5,u7:4},body:`Haalbaar, maar vaak niet direct. Een schuldsanering blijft na afloop nog een aantal jaren zichtbaar op het BKR-overzicht. Volgens BKR is dat nu vijf jaar na het einde van het traject; controleer de actuele termijn op bkr.nl. Zolang die registratie er staat, accepteren de meeste geldverstrekkers geen hypotheek.
Wat ik doe:
- Vraag het BKR-overzicht op en kijk naar de einddatum van alle registraties, niet alleen die van de schuldsanering.
- Breng de situatie in kaart: inkomen, eigen geld, buffer en betaalgedrag sinds de schone lei.
- Bespreek eerlijk de vooruitzichten en wanneer een aanvraag kansrijk wordt.
- Help de klant ondertussen om een buffer en eigen geld op te bouwen.
Leg het BKR-overzicht, je inschatting en wat je met de klant hebt besproken vast in het dossier.`}
  ]},
 {id:'vbj-050',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-26T21:15:00',views:399,tags:['samenwonen','gezamenlijk krediet','toets'],beste:'vbj-050-a3',
  titel:'Gezamenlijk krediet bij samenwonen: wie draagt de last?',
  body:`Een stel heeft een gezamenlijke lening. Bij de hypotheekaanvraag wil maar één partner op de hypotheek. Telt de volledige last van de gezamenlijke lening mee?`,
  antwoorden:[
   {id:'vbj-050-a1',auteur:'u4',datum:'2026-03-27T08:37:00',rA:{},rAdv:{u1:4,u3:5,u7:3},body:`Als de aanvrager hoofdelijk aansprakelijk is, rekenen de meeste geldverstrekkers met de volledige last. Ook al betaalt de partner de helft, juridisch kan de kredietverstrekker het hele bedrag vorderen.
- Controleer de leningovereenkomst.
- Kijk naar het beleid van de geldverstrekker.
- Leg vast hoe je het hebt meegenomen.
Bespreek ook wat er gebeurt bij een relatiebreuk.`},
   {id:'vbj-050-a2',auteur:'u1',datum:'2026-03-28T03:33:00',rA:{u2:4,u3:5,u6:3,u8:3},rAdv:{u2:5,u7:4,u8:4},body:`Ik heb wel gezien dat sommige geldverstrekkers maatwerk bieden als duidelijk is dat de partner meebetaalt. Vraag het na.`},
   {id:'vbj-050-a3',auteur:'u5',datum:'2026-03-29T06:05:00',rA:{u3:3,u6:4},rAdv:{u7:4},body:`Neem in het advies ook de vraag op of de partner niet beter alsnog mee kan lenen. Vaak lost dat meerdere vraagstukken in één keer op.`}
  ]},
 {id:'vbj-051',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-01T09:35:00',views:90,tags:['studieschuld','stelsel','DUO'],beste:'vbj-051-a1',
  titel:'Verschil tussen terugbetaalstelsels studieschuld in de toets',
  body:`Ik zie klanten met een studieschuld onder verschillende terugbetaalstelsels. De ene heeft een kortere en de andere een langere terugbetaaltermijn. Hoe groot is het verschil in de toets en waar let ik op?`,
  antwoorden:[
   {id:'vbj-051-a1',auteur:'u5',datum:'2026-04-01T13:28:00',rA:{},rAdv:{u4:3,u6:5,u7:5,u8:3},body:`Het stelsel bepaalt de terugbetaaltermijn en daarmee de maandlast. Bij een kortere termijn is de maandlast bij dezelfde schuld hoger, wat de leenruimte meer beperkt.
- Stel aan de hand van het DUO-overzicht vast welk stelsel van toepassing is.
- Reken de maandlast volgens de actuele normen.
- Leg het stelsel en de berekening vast in het dossier.
Een verkeerd gekozen stelsel in het adviespakket levert al snel een flink verschil op, dus controleer de invoer.`},
   {id:'vbj-051-a2',auteur:'u6',datum:'2026-04-02T11:51:00',rA:{u1:4,u4:5,u7:4,u8:5},rAdv:{u1:5,u5:4},body:`In het adviespakket kies je het stelsel bij de invoer van de studieschuld. Kijk na het opslaan in de toetsing of de berekende maandlast logisch is ten opzichte van de schuld.`}
  ]},
 {id:'vbj-052',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-03T08:25:00',views:584,tags:['private lease','opzeggen','kosten'],beste:'vbj-052-a1',
  titel:'Private lease opzeggen om meer te kunnen lenen: verstandig?',
  body:`Een klant komt net tekort voor zijn droomhuis. Als hij zijn private lease opzegt, past het wel. Het contract loopt nog twee jaar. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbj-052-a1',auteur:'u2',datum:'2026-04-04T09:03:00',rA:{u8:3},rAdv:{u4:4,u6:5},body:`Kijk eerst wat vroegtijdig beëindigen kost. Leasecontracten kennen vaak een afkoopvergoeding die flink kan oplopen. Daarnaast heeft de klant daarna geen auto meer, dus wat zijn de kosten van een alternatief?
- Vraag de afkoopberekening op bij de leasemaatschappij.
- Vergelijk de totale kosten met het voordeel in leenruimte.
- Leg de afweging vast en laat de klant kiezen.
Soms is een iets goedkopere woning de verstandigere keuze.`},
   {id:'vbj-052-a2',auteur:'u1',datum:'2026-04-05T06:11:00',rA:{u2:4,u3:3,u6:4,u8:4},rAdv:{},body:`Ook goed om te checken: hoe snel is de beëindiging verwerkt op het BKR-overzicht? Plan dat in voordat je de aanvraag indient.`}
  ]},
 {id:'vbj-053',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-08T18:55:00',views:480,tags:['pensioen','consumptief krediet','looptijd'],beste:'vbj-053-a1',
  titel:'Consumptief krediet bij een klant die binnenkort met pensioen gaat',
  body:`Een klant van 64 wil een persoonlijke lening met een looptijd van zeven jaar. Zijn inkomen daalt over een jaar fors door pensionering. Hoe toets ik dit?`,
  antwoorden:[
   {id:'vbj-053-a1',auteur:'u7',datum:'2026-04-09T08:00:00',rA:{u1:4},rAdv:{u5:4},body:`Toets niet alleen op het huidige inkomen, maar ook op het inkomen na pensionering. Een lening die nu past, kan na de AOW-datum te zwaar zijn.
- Vraag een pensioenoverzicht op.
- Bereken de maandlast als percentage van het toekomstige inkomen.
- Leg vast hoe het budget eruitziet na pensionering.
Kredietverstrekkers hanteren hier vaak ook eigen regels voor.`},
   {id:'vbj-053-a2',auteur:'u2',datum:'2026-04-09T14:16:00',rA:{u3:4,u6:4},rAdv:{u4:4,u6:5,u7:3,u8:4},body:`Een kortere looptijd of een kleiner bedrag kan uitkomst bieden. Bespreek ook of er vermogen is dat ingezet kan worden.`}
  ]},
 {id:'vbj-054',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-10T19:05:00',views:588,tags:['studieschuld','DUO','pauze'],beste:null,
  titel:'Jokerjaren bij DUO: invloed op de hypotheektoets?',
  body:`Een klant gebruikt momenteel een jaar waarin hij niet hoeft terug te betalen aan DUO. Hij hoopt dat dit zijn leenruimte vergroot. Is dat zo?`,
  antwoorden:[
   {id:'vbj-054-a1',auteur:'u1',datum:'2026-04-12T00:48:00',rA:{},rAdv:{u2:5,u3:3,u5:4,u8:3},body:`Nee, een tijdelijke betaalpauze verandert niets aan de schuld zelf. In de toets reken je met de maandlast volgens de normen, niet met wat de klant tijdelijk niet betaalt.
- Bespreek dit met de klant zodat er geen verkeerde verwachtingen zijn.
- Leg de berekening vast.
- Check de normen van de geldverstrekker.`}
  ]},
 {id:'vbj-055',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-14T13:25:00',views:236,tags:['expat','BKR','acceptatie'],beste:'vbj-055-a1',
  titel:'Klant net in Nederland zonder kredietgeschiedenis',
  body:`Een expat woont pas een jaar in Nederland. Zijn BKR-overzicht is leeg. Is dat een probleem bij een hypotheekaanvraag?`,
  antwoorden:[
   {id:'vbj-055-a1',auteur:'u4',datum:'2026-04-15T11:26:00',rA:{},rAdv:{u5:3,u7:3},body:`Een leeg BKR-overzicht is geen probleem. Geldverstrekkers kijken wel naar andere aspecten, zoals verblijfsstatus, arbeidscontract en eventuele schulden in het land van herkomst.
- Vraag naar verplichtingen in het buitenland.
- Controleer de voorwaarden van de geldverstrekker voor expats.
- Leg vast welke informatie je hebt ontvangen.`},
   {id:'vbj-055-a2',auteur:'u2',datum:'2026-04-16T01:21:00',rA:{u4:5,u7:3},rAdv:{u3:4},body:`Let op leningen in het buitenland. Die zie je niet, maar ze drukken wel op het budget. Vraag er expliciet naar en leg het antwoord vast.`}
  ]},
 {id:'vbj-056',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-19T15:00:00',views:74,tags:['telefoon','toestelkrediet','BKR'],beste:'vbj-056-a1',
  titel:'Toestelkrediet bij een nieuw telefoonabonnement: let op voor starters',
  body:`Bij een starter zie ik een toestelkrediet op het BKR-overzicht. De klant dacht dat het gewoon een abonnement was. Hoe zwaar telt dit?`,
  antwoorden:[
   {id:'vbj-056-a1',auteur:'u1',datum:'2026-04-20T05:19:00',rA:{u3:5,u5:5},rAdv:{u2:5,u4:4,u8:4},body:`Een geregistreerd toestelkrediet telt mee als een aflopend krediet met de maandlast voor het toestel. Het bedrag is meestal klein, maar het kan net het verschil maken.
- Laat de klant het restant aflossen als dat mogelijk en zinvol is.
- Neem het mee in de toets als het blijft lopen.
- Leg vast dat je het hebt besproken.
Wijs de klant erop dat een nieuw abonnement met toestel tijdens het traject ook een nieuw krediet kan betekenen.`},
   {id:'vbj-056-a2',auteur:'u4',datum:'2026-04-20T10:13:00',rA:{u6:5},rAdv:{u5:5,u8:3},body:`Bij een herstelde achterstand op zo'n toestelkrediet zie ik ook wel eens dat klanten verbaasd zijn. Laat het overzicht altijd vooraf controleren.`}
  ]},
 {id:'vbj-057',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-21T20:35:00',views:147,tags:['echtscheiding','uitkoop','persoonlijke lening'],beste:null,
  titel:'Uitkoop ex-partner met een persoonlijke lening',
  body:`Bij een scheiding wil een klant zijn ex-partner uitkopen. De hypotheek kan niet verhoogd worden, dus hij denkt aan een persoonlijke lening. Wat zijn de risico's?`,
  antwoorden:[
   {id:'vbj-057-a1',auteur:'u5',datum:'2026-04-23T00:25:00',rA:{u6:4,u7:4},rAdv:{u1:4,u4:5,u6:4,u7:4},body:`Een persoonlijke lening voor de uitkoop is geen eigenwoningschuld, dus de rente is niet aftrekbaar. Bovendien is de last vaak hoog door een kortere looptijd. Toets of de klant dit kan dragen.
- Bekijk of verhoging van de hypotheek alsnog mogelijk is bij een andere geldverstrekker.
- Bekijk of de uitkoop fiscaal gunstiger kan worden ingericht.
- Leg vast welke alternatieven je hebt onderzocht.
Overleg bij twijfel met een fiscalist of mediator.`},
   {id:'vbj-057-a2',auteur:'u2',datum:'2026-04-23T03:44:00',rA:{u3:4,u5:4},rAdv:{u5:5,u7:4,u8:3},body:`Bespreek ook wat er gebeurt als het inkomen daalt. Een scheiding is vaak een periode van grote veranderingen.`}
  ]},
 {id:'vbj-058',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-26T12:40:00',views:188,tags:['provisie','transparantie','consumptief krediet'],beste:'vbj-058-a1',
  titel:'Provisie bij kredietbemiddeling: wat moet ik melden?',
  body:`Als ik bemiddel in een persoonlijke lening ontvang ik een vergoeding van de kredietverstrekker. Wat moet ik hierover aan de klant laten weten?`,
  antwoorden:[
   {id:'vbj-058-a1',auteur:'u8',datum:'2026-04-26T16:36:00',rA:{u2:5,u3:3,u5:3,u7:3},rAdv:{},body:`Je moet de klant transparant informeren over je dienstverlening en de wijze waarop je wordt beloond. Dat doe je vooraf, zodat de klant een geïnformeerde keuze kan maken.
- Vermeld de beloningsvorm in je dienstverleningsdocument.
- Licht in het gesprek toe wat je ontvangt.
- Leg vast dat de klant dit heeft ontvangen.
Controleer de actuele regels, want die kunnen per productsoort verschillen.`}
  ]},
 {id:'vbj-059',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-29T13:00:00',views:236,tags:['BKR','herstelmelding','acceptatie'],beste:'vbj-059-a1',
  titel:'Klant met A-codering die al jaren geleden is hersteld',
  body:`Een klant had jaren geleden een achterstand, die na korte tijd is hersteld. De registratie loopt nog. Hij heeft sindsdien netjes betaald. Hoe kansrijk is een aanvraag?`,
  antwoorden:[
   {id:'vbj-059-a1',auteur:'u4',datum:'2026-04-30T13:04:00',rA:{u2:5,u3:5,u5:3,u6:3},rAdv:{u1:4},body:`Een hersteld probleem dat al geruime tijd terug ligt, wordt door veel geldverstrekkers met een goede toelichting geaccepteerd. Het beleid verschilt per partij.
- Vraag een verklaring van de klant over de oorzaak.
- Vraag een bevestiging van herstel op.
- Ga vooraf in overleg met de acceptant.
Leg alles vast.`},
   {id:'vbj-059-a2',auteur:'u1',datum:'2026-05-01T05:14:00',rA:{u6:4},rAdv:{u8:5},body:`Een betalingshistorie van de afgelopen periode helpt om aan te tonen dat het een incident was. Bankafschriften van een aantal maanden laten zien dat de klant zijn verplichtingen nakomt.`}
  ]},
 {id:'vbj-060',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-03T12:35:00',views:19,tags:['zorgplicht','persoonlijke lening','advies'],beste:'vbj-060-a1',
  titel:'Persoonlijke lening voor bruiloft: zorgplicht',
  body:`Een jong stel wil een persoonlijke lening voor hun bruiloft. Ze hebben wel een goed inkomen, maar weinig buffer. Mag ik hier gewoon in bemiddelen?`,
  antwoorden:[
   {id:'vbj-060-a1',auteur:'u8',datum:'2026-05-04T13:31:00',rA:{},rAdv:{},body:`Je mag bemiddelen als het krediet verantwoord en passend is. Bespreek wel het doel en de alternatieven, en wat de lening betekent voor toekomstige plannen zoals een woning.
- Toets de kredietwaardigheid volgens de normen.
- Bespreek het effect op een toekomstige hypotheek.
- Leg je advies en de keuze van de klant vast.`},
   {id:'vbj-060-a2',auteur:'u2',datum:'2026-05-05T17:08:00',rA:{u1:4,u4:5,u6:3,u7:4},rAdv:{},body:`Ik zou het stel vragen of ze over een paar jaar willen kopen. Een lopend krediet kan dan een deel van de leenruimte kosten.`}
  ]},
 {id:'vbj-061',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-05T08:00:00',views:172,tags:['tweede woning','krediet','box 3'],beste:null,
  titel:'Krediet voor een tweede woning of vakantiehuis',
  body:`Een klant wil een vakantiehuis kopen en denkt aan een consumptief krediet als aanvulling op een lening op het vakantiehuis. Hoe beoordelen jullie dat?`,
  antwoorden:[
   {id:'vbj-061-a1',auteur:'u5',datum:'2026-05-06T13:00:00',rA:{u1:4,u2:5,u3:5},rAdv:{u1:4,u2:5,u3:5},body:`Hier ben ik terughoudend. Een recreatiewoning valt in box 3 en geldverstrekkers financieren meestal een lager deel van de waarde dan bij een eigen woning. Een consumptief krediet om het tekort te dichten betekent een duurdere financiering en meer risico.
- Bekijk eerst de eigen middelen en de mogelijkheid om de eigen woning te verhogen, rekening houdend met de fiscale gevolgen.
- Het krediet weegt mee in de toetsing van alle andere financieringen.
- Veel geldverstrekkers accepteren geen inbreng die met een krediet is gefinancierd.
- Kijk naar de bestemming: mag de woning permanent worden bewoond of verhuurd, en zijn huurinkomsten realistisch?
Verantwoorde kredietverlening vraagt dat de klant de totale lasten ook bij tegenvallers kan dragen. Leg de toetsing, de alternatieven en je conclusie vast. Past het niet, zeg dat dan ook duidelijk.`}
  ]},
 {id:'vbj-062',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-09T12:30:00',views:6,tags:['verkoop','aflossen','doorstromer'],beste:null,
  titel:'Toetsing van een krediet dat de klant wil aflossen uit verkoopwinst',
  body:`Een doorstromer heeft een persoonlijke lening. Hij wil die aflossen uit de overwaarde bij verkoop van de huidige woning. Telt de lening in de toets dan nog mee?`,
  antwoorden:[
   {id:'vbj-062-a1',auteur:'u1',datum:'2026-05-10T17:48:00',rA:{u4:4,u5:5,u8:3},rAdv:{u4:3},body:`Dat hangt af van het beleid van de geldverstrekker. Sommigen accepteren een aflossing via de notaris bij verkoop, mits dit in de offerte is opgenomen. Dan telt de lening niet mee.
- Neem de aflossing op in de financieringsopzet.
- Zorg dat de notaris de aflossing uitvoert.
- Leg vast dat dit een voorwaarde is.
Bij een overbruggingskrediet moet de timing goed kloppen.`},
   {id:'vbj-062-a2',auteur:'u5',datum:'2026-05-10T20:47:00',rA:{u1:4},rAdv:{u1:5,u2:4,u3:4},body:`Let erop dat de verkoop definitief is. Bij een voorlopige verkoop wil een geldverstrekker vaak extra zekerheid.`}
  ]},
 {id:'vbj-063',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-14T11:10:00',views:144,tags:['PE','vakbekwaamheid','Wft'],beste:'vbj-063-a1',
  titel:'PE-eisen voor consumptief krediet',
  body:`Ik heb het diploma voor consumptief krediet, maar adviseer er maar zelden over. Moet ik daarvoor ook de PE bijhouden?`,
  antwoorden:[
   {id:'vbj-063-a1',auteur:'u8',datum:'2026-05-15T13:21:00',rA:{u3:4},rAdv:{u1:5,u2:3},body:`Ja. Zolang je adviseert of bemiddelt in consumptief krediet, moet je je vakbekwaamheid actueel houden. Wil je het niet meer doen, dan moet je het ook niet meer aanbieden.
- Controleer je PE-status.
- Leg vast welke modules je hebt gevolgd.
- Bespreek met je kantoor of het product nog wordt aangeboden.`}
  ]},
 {id:'vbj-064',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-16T10:05:00',views:55,tags:['doorlopend krediet','omzetten','toets'],beste:'vbj-064-a1',
  titel:'Kredietlimiet niet opzeggen maar omzetten in aflopend krediet',
  body:`Een klant heeft een doorlopend krediet met een openstaand saldo. Kan hij het omzetten in een persoonlijke lening om de toets gunstiger te maken?`,
  antwoorden:[
   {id:'vbj-064-a1',auteur:'u4',datum:'2026-05-16T22:02:00',rA:{u8:5},rAdv:{u3:4,u5:5,u8:3},body:`Omzetten kan gunstig zijn, omdat bij een persoonlijke lening de maandlast telt en niet de limiet. Het saldo blijft wel gewoon staan.
- Vergelijk de toetslast van beide vormen.
- Kijk naar de rente en de looptijd van de nieuwe lening.
- Zorg dat het doorlopend krediet daadwerkelijk wordt beëindigd.
Leg de vergelijking vast.`},
   {id:'vbj-064-a2',auteur:'u2',datum:'2026-05-17T00:01:00',rA:{u3:5,u7:4},rAdv:{u6:5},body:`Een vast aflossingsschema helpt de klant ook in discipline. Bij een doorlopend krediet blijft het saldo vaak langer staan.`}
  ]},
 {id:'vbj-065',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-20T08:05:00',views:292,tags:['BKR','aanvraag','afwijking'],beste:null,
  titel:'Wat als de geldverstrekker een registratie ziet die ik niet zag?',
  body:`Bij een aanvraag kwam de geldverstrekker met een registratie die niet op het overzicht stond dat de klant mij gaf. Hoe kan dat en wat nu?`,
  antwoorden:[
   {id:'vbj-065-a1',auteur:'u1',datum:'2026-05-20T12:22:00',rA:{u3:4,u4:4},rAdv:{u3:4,u4:4,u5:5,u7:4},body:`Het overzicht kan verouderd zijn of de klant heeft een overzicht met minder detail gestuurd. Vraag de klant direct om een nieuw volledig overzicht.
- Zoek uit wat er is misgegaan.
- Leg vast wat je hebt ontvangen en wanneer.
- Reken het advies opnieuw door.`},
   {id:'vbj-065-a2',auteur:'u8',datum:'2026-05-21T08:02:00',rA:{u2:5,u7:4},rAdv:{u5:4},body:`Leg goed vast welk overzicht je van de klant kreeg en op welke datum. Daarmee laat je zien dat je zorgvuldig hebt gewerkt.`}
  ]},
 {id:'vbj-066',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-25T10:45:00',views:469,tags:['lease','fiets','werkgever'],beste:'vbj-066-a1',
  titel:'Lease van een e-bike via een werkgeversregeling',
  body:`Een klant least een e-bike via zijn werkgever. Telt dat mee in de hypotheektoets?`,
  antwoorden:[
   {id:'vbj-066-a1',auteur:'u4',datum:'2026-05-26T01:34:00',rA:{u1:3},rAdv:{u5:3},body:`Een fietsleaseregeling via de werkgever loopt meestal via het salaris en is geen consumptief krediet op naam van de klant. Het staat dan niet op het BKR-overzicht.
- Kijk op de loonstrook of en hoe de bijtelling of inhouding plaatsvindt.
- Neem het mee in het budget.
- Leg vast hoe je het hebt beoordeeld.
Controleer bij twijfel de voorwaarden van de geldverstrekker.`}
  ]},
 {id:'vbj-067',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-28T21:40:00',views:321,tags:['verbouwing','buffer','krediet'],beste:'vbj-067-a1',
  titel:'Persoonlijke lening als buffer tijdens een verbouwing',
  body:`Een klant wil naast een bouwdepot een persoonlijke lening als buffer voor tegenvallers. Is dat gangbaar?`,
  antwoorden:[
   {id:'vbj-067-a1',auteur:'u2',datum:'2026-05-29T15:59:00',rA:{},rAdv:{u3:3,u5:5,u6:3,u8:5},body:`Het kan, maar het is duurder en telt mee in de toets. Een alternatief is een iets ruimer bouwdepot met een post onvoorzien.
- Bespreek het nut van een post onvoorzien.
- Vergelijk de kosten.
- Leg de afweging vast.`},
   {id:'vbj-067-a2',auteur:'u5',datum:'2026-05-30T20:03:00',rA:{u3:4},rAdv:{u8:5},body:`Een bouwdepot met een post onvoorzien kan alleen als de geldverstrekker dat accepteert. Controleer dat. Een ongebruikt restant van het bouwdepot kun je na afloop aflossen.`}
  ]},
 {id:'vbj-068',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-01T16:50:00',views:237,tags:['BKR','jongeren','registratie'],beste:null,
  titel:'Klant met een minderjarige registratie',
  body:`Een jonge klant heeft een registratie van een krediet dat hij heeft afgesloten kort nadat hij volwassen werd. Hij vindt het vervelend dat het er nog op staat. Wat kan ik hem adviseren?`,
  antwoorden:[
   {id:'vbj-068-a1',auteur:'u4',datum:'2026-06-02T16:50:00',rA:{u3:4,u2:5},rAdv:{u3:4,u2:5},body:`Een juiste registratie kun je niet laten verwijderen. Wel kun je het overzicht samen bekijken.
- Staat het krediet zonder achterstandscode geregistreerd, dan is het geen negatieve registratie. Het weegt mee in de toetsing zolang het loopt, en na aflossing blijft het nog een periode zichtbaar. Controleer de actuele bewaartermijn op bkr.nl.
- Is er een achterstand geregistreerd, kijk dan of die klopt en of er een herstelmelding is.
- Vindt de klant dat de registratie onjuist is, dan moet hij eerst de kredietverstrekker vragen om correctie. Helpt dat niet, dan zijn er klachtprocedures bij BKR.
Praktisch advies: los het krediet zo mogelijk af, betaal op tijd en zeg ongebruikte limieten op. Leg in het dossier vast wat je op het overzicht hebt gezien en wat je de klant hebt geadviseerd.`}
  ]},
 {id:'vbj-069',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-03T08:15:00',views:325,tags:['voorlichting','maximale hypotheek','krediet'],beste:'vbj-069-a2',
  titel:'Hoe maak je de klant bewust van het effect van een krediet op de maximale hypotheek?',
  body:`Veel klanten schrikken als ze horen hoeveel hun krediet kost aan leenruimte. Hoe maken jullie dat duidelijk zonder dat het een preek wordt?`,
  antwoorden:[
   {id:'vbj-069-a1',auteur:'u1',datum:'2026-06-03T15:01:00',rA:{u5:3,u6:5},rAdv:{u2:4,u5:4,u6:5,u7:4},body:`Ik laat in het adviespakket een berekening zien met en zonder het krediet. Het verschil in maximale hypotheek spreekt meestal voor zich.
- Laat beide uitkomsten zien.
- Leg uit hoe de berekening werkt in eenvoudige woorden.
- Leg de vergelijking vast in het dossier.`},
   {id:'vbj-069-a2',auteur:'u6',datum:'2026-06-04T11:27:00',rA:{u2:4},rAdv:{u1:5,u2:4,u7:3},body:`In het adviespakket kun je een variant aanmaken. Dupliceer het dossier of de berekening, verwijder de verplichting in de variant en vergelijk de uitkomsten naast elkaar.`}
  ]},
 {id:'vbj-070',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-07T11:10:00',views:253,tags:['studieschuld','rente','dossier'],beste:'vbj-070-a1',
  titel:'Studieschuld en de effectieve rente: wat zet ik in het dossier?',
  body:`In de toets speelt de rente op de studieschuld een rol. Moet ik daarvan bewijs in het dossier hebben?`,
  antwoorden:[
   {id:'vbj-070-a1',auteur:'u5',datum:'2026-06-07T17:58:00',rA:{u4:5},rAdv:{u4:3,u6:3,u7:3,u8:4},body:`Ja, leg de bron van de rente vast, bij voorkeur het overzicht uit Mijn DUO. Daarop staan de hoofdsom, de rente en de terugbetaalgegevens.
- Bewaar het overzicht met datum.
- Leg vast welke rente je hebt gebruikt.
- Controleer of de gegevens actueel zijn voor de aanvraag.`}
  ]},
 {id:'vbj-071',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-10T10:25:00',views:266,tags:['na passeren','krediet','voorlichting'],beste:null,
  titel:'Krediet afsluiten na passeren: zijn er beperkingen?',
  body:`Een klant vraagt of hij na het passeren van de hypotheek gewoon een nieuwe lening mag afsluiten voor de inrichting. Wat vertellen jullie?`,
  antwoorden:[
   {id:'vbj-071-a1',auteur:'u4',datum:'2026-06-10T17:50:00',rA:{},rAdv:{u2:4,u3:3,u6:3,u7:5},body:`Na het passeren is de klant vrij een nieuwe lening af te sluiten, maar bespreek de gevolgen. Een nieuwe lening drukt op het budget en kan later een verhoging of oversluiting lastiger maken.
- Bespreek of de klant dit kan dragen.
- Kijk naar alternatieven zoals sparen.
- Leg vast dat je het hebt besproken.`},
   {id:'vbj-071-a2',auteur:'u2',datum:'2026-06-11T14:17:00',rA:{u4:5,u5:4},rAdv:{u1:4,u6:3,u8:5},body:`Ik geef klanten standaard een eenvoudig budgetoverzicht mee na het passeren. Daarmee zien ze zelf of er ruimte is voor extra lasten.`}
  ]},
 {id:'vbj-072',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-16T09:00:00',views:562,tags:['variabele rente','doorlopend krediet','risico'],beste:'vbj-072-a1',
  titel:'Hoe toets je een krediet met een variabele rente?',
  body:`Een klant heeft een doorlopend krediet met een variabele rente. Moet ik rekening houden met een stijging van de rente in het budget?`,
  antwoorden:[
   {id:'vbj-072-a1',auteur:'u2',datum:'2026-06-16T13:00:00',rA:{u4:4,u8:3},rAdv:{u1:3},body:`In de toets voor de hypotheek telt de limiet volgens de normen, niet de rente. In het budget is het wel goed om met een hogere rente te rekenen, zodat de klant weet wat een stijging betekent.
- Laat een scenario zien met een hogere rente.
- Bespreek of vast aflossen een optie is.
- Leg de bespreking vast.`}
  ]},
 {id:'vbj-073',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-18T21:15:00',views:294,tags:['compliance','collega','zorgplicht'],beste:'vbj-073-a1',
  titel:'Collega adviseert klant krediet op te nemen voor kosten koper: hoe ga ik daarmee om?',
  body:`Ik zag in een dossier van een collega dat hij een klant heeft geadviseerd de kosten koper te financieren met een persoonlijke lening. Ik vind dat niet passend. Hoe pak ik dit aan?`,
  antwoorden:[
   {id:'vbj-073-a1',auteur:'u8',datum:'2026-06-18T22:56:00',rA:{u6:5},rAdv:{},body:`Bespreek het eerst met je collega en vraag naar de onderbouwing. Misschien is er een goede reden die niet in het dossier staat. Is die er niet, schakel dan compliance in.
- Kijk of het advies goed is vastgelegd.
- Bespreek de risico's voor de klant.
- Leg je bevinding en de afspraken vast.
Het doel is het beschermen van de klant, niet het beschuldigen van een collega.`},
   {id:'vbj-073-a2',auteur:'u5',datum:'2026-06-19T19:49:00',rA:{u2:3,u8:4},rAdv:{u2:3,u4:3,u8:5},body:`Een intercollegiale toets helpt hierbij. Bij ons bespreken we regelmatig dossiers met elkaar, zonder dat het een beschuldiging is.`}
  ]},
 {id:'vbj-074',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-21T20:35:00',views:349,tags:['studieschuld','buitenland','toets'],beste:null,
  titel:'Telt een studieschuld uit het buitenland mee?',
  body:`Een klant heeft in het buitenland gestudeerd en heeft daar een studielening. Hoe neem ik die mee?`,
  antwoorden:[
   {id:'vbj-074-a1',auteur:'u1',datum:'2026-06-22T04:31:00',rA:{u2:4,u7:5},rAdv:{u2:5,u3:5,u5:3,u8:5},body:`Ook een buitenlandse studielening is een verplichting die je meeneemt. De rekenwijze kan afwijken van een DUO-schuld; vraag de geldverstrekker hoe ze ermee omgaan.
- Vraag een overzicht van de lening op.
- Neem de werkelijke maandlast mee in het budget.
- Leg vast welke informatie je hebt.`},
   {id:'vbj-074-a2',auteur:'u4',datum:'2026-06-23T01:15:00',rA:{},rAdv:{u3:4,u5:4},body:`Laat een vertaling maken als het overzicht niet in het Nederlands of Engels is. Dat voorkomt vertraging bij de acceptatie.`}
  ]},
 {id:'vbj-075',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-26T17:15:00',views:596,tags:['overlijden','nalatenschap','krediet'],beste:null,
  titel:'Krediet op naam van een overleden partner',
  body:`Een weduwe wil haar hypotheek aanpassen. Op het BKR-overzicht staat nog een doorlopend krediet dat op naam van haar overleden partner en haar samen stond. Hoe pakken jullie dit aan en wat vraag je op bij de kredietverstrekker?`,
  antwoorden:[
   {id:'vbj-075-a1',auteur:'u1',datum:'2026-06-27T21:15:00',rA:{u8:5,u7:5,u6:4,u5:4},rAdv:{u7:5,u5:4},body:`Bij een gezamenlijk krediet blijft de langstlevende meestal hoofdelijk aansprakelijk. Het krediet telt dus mee in de toetsing totdat het is afgelost of beëindigd.
Vraag bij de kredietverstrekker:
- het actuele saldo en de limiet;
- of het krediet op haar naam doorloopt of is opgezegd;
- of er een overlijdensdekking aan het krediet was gekoppeld en of die heeft uitgekeerd;
- of er achterstanden zijn.
Laat de weduwe de akte van overlijden of een verklaring van erfrecht meesturen. Wil ze het krediet niet houden, laat het dan aflossen en opzeggen en vraag een bewijs van beëindiging; dat helpt bij de aanvraag tot het BKR is bijgewerkt. Controleer daarna het BKR-overzicht. Leg de correspondentie met de kredietverstrekker en de afspraken in het dossier vast.`}
  ]},
 {id:'vbj-076',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-29T21:10:00',views:459,tags:['opzeggen','BKR','afmelding'],beste:'vbj-076-a1',
  titel:'Krediet opgezegd, maar nog steeds zichtbaar op het BKR-overzicht',
  body:`Een klant heeft een doorlopend krediet een maand geleden opgezegd. Op het nieuwe BKR-overzicht staat het nog als lopend. De aanvraag moet binnenkort de deur uit. Hoe lossen jullie dit op?`,
  antwoorden:[
   {id:'vbj-076-a1',auteur:'u1',datum:'2026-06-30T11:45:00',rA:{u3:4,u5:4,u8:4},rAdv:{u5:3,u8:4},body:`De afmelding is de verantwoordelijkheid van de kredietverstrekker en kan even duren. Vraag de klant om een schriftelijke bevestiging van beëindiging, met datum en een saldo van nul.
- Stuur die bevestiging mee met de aanvraag.
- Vraag de geldverstrekker of dit voldoende is.
- Leg in het dossier vast wanneer is opgezegd en wat je hebt aangeleverd.
Lukt het niet, laat de klant dan contact opnemen met de kredietverstrekker om de afmelding te versnellen.`},
   {id:'vbj-076-a2',auteur:'u4',datum:'2026-06-30T22:46:00',rA:{},rAdv:{u8:5},body:`Mijn ervaring is dat de meeste acceptanten een duidelijke beëindigingsbrief accepteren. Een mail van de klantenservice is vaak niet genoeg, dus vraag om een officiële bevestiging.`}
  ]},
 {id:'vbj-077',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-03T15:40:00',views:594,tags:['familielening','onderhandse lening','toets'],beste:'vbj-077-a1',
  titel:'Familielening naast de hypotheek: telt die mee in de toets?',
  body:`Een starter krijgt een lening van zijn ouders voor een deel van de koopsom. De rest gaat via een geldverstrekker. Telt de familielening mee in de maximale hypotheek?`,
  antwoorden:[
   {id:'vbj-077-a1',auteur:'u5',datum:'2026-07-03T23:50:00',rA:{},rAdv:{u2:3,u4:3,u6:4,u7:3},body:`Een lening van de ouders is ook een lening, en de lasten moeten in de toets worden meegenomen volgens de normen. Er is een uitzondering mogelijk als de ouders de lening achtergesteld en zonder vaste verplichtingen verstrekken, maar dat hangt af van het beleid van de geldverstrekker.
- Leg de lening vast in een schriftelijke overeenkomst.
- Kijk naar de fiscale regels voor eigenwoningschuld als de lening voor de woning is.
- Controleer de voorwaarden van de geldverstrekker.
Leg vast hoe je de lening hebt meegenomen.`},
   {id:'vbj-077-a2',auteur:'u2',datum:'2026-07-05T00:19:00',rA:{u1:3,u4:5,u5:5,u6:5},rAdv:{u3:3,u5:4},body:`Bespreek ook wat er met de lening gebeurt bij overlijden van een van de ouders. Dat kan erfrechtelijke gevolgen hebben voor broers en zussen.`}
  ]},
 {id:'vbj-078',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-06T19:10:00',views:306,tags:['schuldhulp','zorgplicht','signalering'],beste:'vbj-078-a1',
  titel:'Signalen van problematische schulden tijdens het adviesgesprek',
  body:`In een gesprek over een hypotheekverhoging blijkt dat de klant meerdere kredieten heeft en regelmatig achterloopt met betalingen. Hij wil met de verhoging alles oplossen. Wat is dan passend?`,
  antwoorden:[
   {id:'vbj-078-a1',auteur:'u2',datum:'2026-07-07T02:17:00',rA:{u3:5},rAdv:{},body:`Kijk eerst naar de oorzaak. Een herfinanciering kan helpen, maar als het uitgavenpatroon hetzelfde blijft, lost het weinig op. Soms is het beter om de klant door te verwijzen naar schuldhulpverlening of een budgetcoach.
- Breng alle schulden en lasten in kaart.
- Toets of de nieuwe financiering verantwoord is.
- Leg je afweging en het advies vast.
Een hypotheek is geen oplossing als het probleem in het budget zit.`},
   {id:'vbj-078-a2',auteur:'u8',datum:'2026-07-08T06:28:00',rA:{},rAdv:{u2:3},body:`Leg ook vast wanneer je besluit niet te adviseren of door te verwijzen. Dat beschermt de klant en jou.`},
   {id:'vbj-078-a3',auteur:'u5',datum:'2026-07-08T08:59:00',rA:{u2:3,u4:5,u7:3,u8:5},rAdv:{u2:3},body:`In de praktijk combineer ik dit soms: eerst een paar maanden budgetbegeleiding, daarna opnieuw kijken. Klanten waarderen dat meer dan je zou denken.`}
  ]},
 {id:'vbj-079',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-11T20:35:00',views:371,tags:['CRM','herinnering','opvolging'],beste:null,
  titel:'Herinnering instellen voor einddatum krediet in het CRM',
  body:`Een klant kan over een jaar meer lenen omdat zijn autolening dan afloopt. Ik wil hem op dat moment benaderen. Hoe regelen jullie dat in het CRM?`,
  antwoorden:[
   {id:'vbj-079-a1',auteur:'u6',datum:'2026-07-12T20:40:00',rA:{u1:3,u4:4,u8:4},rAdv:{u4:5,u8:5},body:`Maak een taak of herinnering aan op de klantkaart met een datum vlak voor de einddatum van het krediet. Zet in de omschrijving waarom je contact opneemt.
- Koppel de taak aan de adviseur die het dossier beheert.
- Leg de einddatum van het krediet vast bij de verplichtingen.
- Controleer of de klant toestemming heeft gegeven voor contact.
Zo valt het niet tussen wal en schip als er iemand afwezig is.`},
   {id:'vbj-079-a2',auteur:'u8',datum:'2026-07-12T21:43:00',rA:{u2:5,u6:4},rAdv:{u4:5,u7:5},body:`Goed om het contact ook te koppelen aan een actualisatie van de klantgegevens. Dan is je dossier meteen weer bij.`}
  ]},
 {id:'vbj-080',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-14T17:30:00',views:311,tags:['studieschuld','aflossing','bewijs'],beste:'vbj-080-a1',
  titel:'Studieschuld volledig afgelost: welk bewijs vragen geldverstrekkers?',
  body:`Een klant heeft zijn studieschuld net volledig afgelost. Welk bewijs moet ik aanleveren zodat de last niet meer meetelt?`,
  antwoorden:[
   {id:'vbj-080-a1',auteur:'u1',datum:'2026-07-15T12:12:00',rA:{u3:3,u5:3,u6:5,u7:3},rAdv:{u5:5},body:`Vraag een actueel overzicht uit Mijn DUO op, waarop een schuld van nul zichtbaar is. Sommige geldverstrekkers accepteren ook een bevestiging van DUO van de volledige aflossing.
- Bewaar het bewijs met datum in het dossier.
- Controleer of de aflossing echt verwerkt is.
- Leg vast dat de studieschuld niet meer in de toets is meegenomen.`}
  ]},
 {id:'vbj-081',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-18T21:20:00',views:592,tags:['regelgeving','consumptief krediet','richtlijn'],beste:null,
  titel:'Nieuwe Europese regels voor consumptief krediet: wat verandert er voor adviseurs?',
  body:`Ik lees dat de Europese regels voor consumentenkrediet worden herzien en dat ook kleinere kredieten en achteraf betalen eronder gaan vallen. Wat betekent dit voor ons als adviseurs?`,
  antwoorden:[
   {id:'vbj-081-a1',auteur:'u8',datum:'2026-07-19T18:17:00',rA:{u2:4},rAdv:{u1:4},body:`De herziene Europese richtlijn moet in Nederlandse wetgeving worden omgezet. Welke verplichtingen precies voor adviseurs gaan gelden, volgt uit die implementatie. Houd de berichtgeving van de toezichthouder en de brancheorganisaties in de gaten.
- Pas je werkwijze en documentatie aan zodra de regels definitief zijn.
- Let op mogelijke gevolgen voor de kredietwaardigheidstoets en de informatie aan de klant.
- Leg vast hoe je je kantoorprocessen hebt aangepast.
Tot die tijd gelden de huidige regels.`}
  ]},
 {id:'vbj-082',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-19T14:15:00',views:239,tags:['verduurzaming','energiebespaarlening','toets'],beste:'vbj-082-a1',
  titel:'Energiebespaarlening en de hypotheektoets',
  body:`Een klant heeft een lening voor energiebesparende maatregelen afgesloten. Telt die mee in de hypotheektoets, en is die op het BKR-overzicht zichtbaar?`,
  antwoorden:[
   {id:'vbj-082-a1',auteur:'u5',datum:'2026-07-20T16:20:00',rA:{u1:5,u2:5,u4:3,u6:4},rAdv:{u3:4},body:`Een lening voor verduurzaming is een verplichting die je meeneemt in de toets, ook als het een lening met gunstige voorwaarden is. Controleer of en hoe de lening is geregistreerd en welke last de geldverstrekker aanhoudt.
- Vraag het leningcontract op.
- Neem de maandlast mee volgens de normen.
- Leg vast hoe je het hebt meegenomen.
Bij oversluiten kun je bespreken of meenemen in de hypotheek gunstiger is.`},
   {id:'vbj-082-a2',auteur:'u1',datum:'2026-07-21T00:52:00',rA:{u4:3,u5:3,u7:5},rAdv:{u5:4},body:`Let op of de lening aan de woning gekoppeld is. Bij verkoop moet die soms worden afgelost, en dat moet in de financieringsopzet passen.`}
  ]},
 {id:'vbj-083',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-24T14:55:00',views:534,tags:['private lease','na passeren','advies'],beste:'vbj-083-a1',
  titel:'Private lease direct na de hypotheek: wat zeg ik tegen de klant?',
  body:`Een klant vertelt dat hij direct na het passeren een private lease auto wil nemen. Hij zegt dat het nu niet meetelt omdat het nog niet getekend is. Hoe reageren jullie?`,
  antwoorden:[
   {id:'vbj-083-a1',auteur:'u4',datum:'2026-07-24T23:39:00',rA:{u1:4,u2:5},rAdv:{u5:5},body:`Leg uit dat de aanvraag moet uitgaan van een juist en volledig beeld. Als de klant al vaststaande plannen heeft, is het niet netjes om die te verzwijgen. Bovendien moet de last ook na het passeren betaalbaar zijn.
- Neem de geplande lease mee in het budget.
- Bespreek of de financiering dan nog verantwoord is.
- Leg het gesprek vast.
Weigert de klant openheid, overleg dan met compliance.`},
   {id:'vbj-083-a2',auteur:'u8',datum:'2026-07-26T00:38:00',rA:{u2:3,u3:3,u4:4,u7:5},rAdv:{u4:5,u5:3},body:`Belangrijk punt. Leg vast wat de klant heeft gezegd en wat je hebt geadviseerd. Dat beschermt je bij een latere klacht.`}
  ]},
 {id:'vbj-084',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-27T08:40:00',views:362,tags:['private lease','partner','gezamenlijk'],beste:'vbj-084-a1',
  titel:'Leasecontract van de partner: meenemen in gezamenlijke aanvraag?',
  body:`Bij een gezamenlijke aanvraag heeft alleen de partner een private lease contract. Moet ik dat meenemen?`,
  antwoorden:[
   {id:'vbj-084-a1',auteur:'u1',datum:'2026-07-28T11:10:00',rA:{u6:4,u8:3},rAdv:{},body:`Ja, bij een gezamenlijke aanvraag tellen de verplichtingen van beide aanvragers mee. Een leasecontract van één van beiden wordt dus gewoon meegenomen.
- Vraag het contract op.
- Neem de last mee volgens het beleid van de geldverstrekker.
- Leg vast hoe je het hebt meegenomen.`}
  ]},
 {id:'vbj-085',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-01T18:50:00',views:507,tags:['arbeidsongeschiktheid','krediet','risico'],beste:'vbj-085-a1',
  titel:'Arbeidsongeschiktheid en een lopend krediet',
  body:`Een klant met een hoog consumptief krediet vraagt wat er gebeurt als hij arbeidsongeschikt raakt. Hoe adviseren jullie hierover?`,
  antwoorden:[
   {id:'vbj-085-a1',auteur:'u3',datum:'2026-08-02T18:49:00',rA:{u1:4,u2:3},rAdv:{},body:`Breng in kaart wat het inkomen wordt bij arbeidsongeschiktheid en of de lasten dan nog te dragen zijn. Een krediet blijft doorlopen, ook als het inkomen daalt.
- Bekijk de dekking van een eventuele AOV of werkgeversregeling.
- Bespreek of een kredietverzekering of woonlastenverzekering nodig is.
- Leg je advies en de keuze van de klant vast.`},
   {id:'vbj-085-a2',auteur:'u2',datum:'2026-08-03T15:39:00',rA:{u3:4,u7:3},rAdv:{u1:3,u4:3,u6:3,u7:3},body:`Een buffer is vaak de beste eerste stap. Bij een hoog krediet zou ik ook kijken naar versneld aflossen om het risico te verkleinen.`}
  ]},
 {id:'vbj-086',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-03T20:40:00',views:318,tags:['oversluiten','toets','krediet'],beste:'vbj-086-a1',
  titel:'Oversluiten zonder verhoging: tellen kredieten dan mee?',
  body:`Een klant wil zijn hypotheek oversluiten naar een lagere rente, zonder verhoging. Hij heeft inmiddels een persoonlijke lening. Moet hij opnieuw volledig getoetst worden?`,
  antwoorden:[
   {id:'vbj-086-a1',auteur:'u5',datum:'2026-08-05T00:38:00',rA:{u1:4,u8:4},rAdv:{u1:3,u2:5,u4:5,u7:4},body:`Bij oversluiten wordt in principe opnieuw getoetst, maar de normen bieden onder voorwaarden ruimte om af te wijken als de lasten niet stijgen. Of de geldverstrekker daar gebruik van maakt, verschilt.
- Controleer de actuele normen en het beleid van de geldverstrekker.
- Leg vast of en waarom je een uitzondering toepast.
- Neem de persoonlijke lening mee in het budget.`},
   {id:'vbj-086-a2',auteur:'u4',datum:'2026-08-05T13:37:00',rA:{u2:3},rAdv:{u1:3,u2:3,u3:3,u8:4},body:`In de praktijk merk ik dat de huidige geldverstrekker bij een rentemiddeling soms soepeler is dan een nieuwe geldverstrekker. Vergelijk dus beide routes.`}
  ]},
 {id:'vbj-087',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-08T12:55:00',views:216,tags:['creditcard','starter','BKR'],beste:null,
  titel:'Starter is extra kaarthouder op creditcard van de ouders',
  body:`Een starter heeft een creditcard die hoort bij de rekening van haar ouders. Staat dit op haar BKR-overzicht en telt het mee?`,
  antwoorden:[
   {id:'vbj-087-a1',auteur:'u4',datum:'2026-08-08T19:45:00',rA:{},rAdv:{u1:3,u5:3,u6:4},body:`Meestal staat het krediet op naam van de hoofdkaarthouder en niet op naam van een extra kaarthouder. Controleer het BKR-overzicht van de starter.
- Staat het er niet op, leg dan vast dat het niet op haar naam staat.
- Staat het er wel op, neem het dan mee als doorlopend krediet.
- Bespreek of de kaart nodig is.`}
  ]},
 {id:'vbj-088',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-11T19:00:00',views:211,tags:['verhoging','krediet','actualisatie'],beste:'vbj-088-a1',
  titel:'Hypotheekverhoging bij bestaande klant met nieuw krediet',
  body:`Een bestaande klant wil zijn hypotheek verhogen. Sinds de vorige aanvraag heeft hij een autolening afgesloten. Hoe ga ik hiermee om?`,
  antwoorden:[
   {id:'vbj-088-a1',auteur:'u1',datum:'2026-08-12T16:20:00',rA:{u4:4,u8:5},rAdv:{u3:5,u4:5,u7:5},body:`Neem de nieuwe lening mee in de toets en in het budget. Vraag een actueel BKR-overzicht op en het contract van de autolening.
- Actualiseer de inventarisatie.
- Reken de maximale verhoging door.
- Leg vast hoe de lening is meegenomen.`},
   {id:'vbj-088-a2',auteur:'u5',datum:'2026-08-13T08:02:00',rA:{},rAdv:{},body:`Kijk ook of meefinancieren van de autolening verstandig is. Fiscaal valt dat deel dan buiten de eigenwoningschuld.`}
  ]},
 {id:'vbj-089',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-16T12:30:00',views:202,tags:['buffer','aflossen','afweging'],beste:null,
  titel:'Mag ik de klant adviseren een krediet af te lossen met zijn buffer?',
  body:`Een klant kan meer lenen als hij zijn persoonlijke lening aflost met zijn spaargeld. Daarna heeft hij weinig buffer. Wat is passend?`,
  antwoorden:[
   {id:'vbj-089-a1',auteur:'u5',datum:'2026-08-18T07:30:00',rA:{u6:5,u7:5,u2:4},rAdv:{u7:5,u2:4},body:`Het mag, maar alleen als het passend is voor deze klant. Meer lenen is geen doel op zich.
- Bepaal welke buffer de klant nodig heeft voor onverwachte uitgaven en inkomensrisico's. Controleer de actuele richtlijnen van het Nibud.
- Kijk wat er na aflossing overblijft voor kosten koper, verhuizing en inrichting.
- Bespreek alternatieven: gedeeltelijk aflossen, een lager hypotheekbedrag of later aankopen.
- Laat zien wat er gebeurt bij een tegenvaller, zoals een kapotte auto of inkomensdaling.
Het voordeel is reëel: een krediet aflossen verlaagt de lasten en verbetert de leenruimte. Maar zonder buffer kan een kleine tegenvaller tot betalingsproblemen leiden. Leg in het dossier vast welke buffer er overblijft, welke risico's je hebt besproken en dat de klant bewust kiest. Raad je het af, zeg dat dan ook duidelijk.`}
  ]},
 {id:'vbj-090',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-18T12:15:00',views:156,tags:['samenwerking','krediet','complex'],beste:'vbj-090-a2',
  titel:'Wanneer schakel je een collega in voor krediet in de toets?',
  body:`Bij complexe situaties met meerdere kredieten, lease en een studieschuld twijfel ik soms over de juiste rekenwijze. Hoe organiseren jullie dat intern?`,
  antwoorden:[
   {id:'vbj-090-a1',auteur:'u5',datum:'2026-08-18T15:05:00',rA:{u3:5},rAdv:{},body:`Wij hebben een vast moment voor dossierbespreking. Twijfels over rekenwijzen bespreken we daar, en de uitkomst leggen we vast in het dossier.
- Maak een korte notitie met de vraag.
- Leg de uitkomst en de bron vast.
- Overleg met de acceptant bij twijfel.`},
   {id:'vbj-090-a2',auteur:'u1',datum:'2026-08-19T04:26:00',rA:{u2:3,u4:5},rAdv:{u3:5},body:`Ik bel bij twijfel gewoon de acceptatie. Zij weten precies hoe zij rekenen, en dat scheelt later discussie.`},
   {id:'vbj-090-a3',auteur:'u8',datum:'2026-08-20T08:16:00',rA:{u2:4,u7:5},rAdv:{u3:4,u5:5,u7:5},body:`Prima, maar leg het telefonische advies van de acceptant wel vast met datum en naam van de afdeling.`}
  ]},
 {id:'vbj-091',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-22T19:20:00',views:547,tags:['scheiding','overlijden','krediet'],beste:'vbj-091-a1',
  titel:'Overlijdensrisico bij gezamenlijk krediet na scheiding',
  body:`Na een scheiding hebben twee ex-partners nog een gezamenlijke lening. Een van hen vraagt wat er gebeurt als de ander overlijdt. Hoe adviseren jullie?`,
  antwoorden:[
   {id:'vbj-091-a1',auteur:'u3',datum:'2026-08-23T04:43:00',rA:{u4:5,u6:3},rAdv:{u2:5,u7:4},body:`Bij een hoofdelijke lening kan de kredietverstrekker bij overlijden het volledige bedrag van de nabestaande partner vorderen. Of er een verzekering is die dekt, hangt af van wat er destijds is afgesloten.
- Vraag de leningvoorwaarden op.
- Kijk of er een kredietverzekering of overlijdensrisicoverzekering is.
- Leg je advies vast.
Het beste is meestal om de lening te splitsen of af te lossen.`}
  ]},
 {id:'vbj-092',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-26T16:30:00',views:129,tags:['tijdelijk contract','krediet','toets'],beste:null,
  titel:'Krediet in de toets bij tijdelijk contract',
  body:`Een klant heeft een tijdelijk contract met een intentieverklaring. Hij heeft ook een persoonlijke lening. Hoe weegt dat samen?`,
  antwoorden:[
   {id:'vbj-092-a1',auteur:'u4',datum:'2026-08-27T16:40:00',rA:{u3:4,u7:3},rAdv:{u5:5,u6:5,u8:3},body:`Bij een tijdelijk contract met intentieverklaring kan het inkomen onder voorwaarden worden meegenomen. De persoonlijke lening telt gewoon mee in de toets.
- Controleer de voorwaarden voor de intentieverklaring.
- Neem de lening mee met de maandlast.
- Leg vast hoe je het inkomen en de lasten hebt bepaald.`},
   {id:'vbj-092-a2',auteur:'u2',datum:'2026-08-28T03:50:00',rA:{u5:3},rAdv:{u1:3,u3:4,u4:4,u5:3},body:`Bespreek ook wat er gebeurt als het contract niet wordt verlengd. Een lening loopt dan door.`}
  ]},
 {id:'vbj-093',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-29T09:25:00',views:479,tags:['klantprofiel','consumptief krediet','inventarisatie'],beste:'vbj-093-a1',
  titel:'Advies over consumptief krediet: welke informatie in het klantprofiel?',
  body:`Wat neem je op in het klantprofiel bij een advies over consumptief krediet? Is het net zo uitgebreid als bij een hypotheek?`,
  antwoorden:[
   {id:'vbj-093-a1',auteur:'u8',datum:'2026-08-30T14:43:00',rA:{u1:3,u7:4},rAdv:{u2:4,u4:3,u6:4,u7:4},body:`Het profiel moet voldoende informatie bevatten om te beoordelen of het krediet verantwoord en passend is. Dat betekent inkomen, lasten, verplichtingen, doel van het krediet en de risicobereidheid.
- Leg het bestedingsdoel vast.
- Breng het budget in kaart.
- Leg vast welke alternatieven zijn besproken.
De omvang hangt af van de situatie, maar te weinig is een risico.`},
   {id:'vbj-093-a2',auteur:'u2',datum:'2026-08-31T16:09:00',rA:{u8:3},rAdv:{},body:`Bij een klein krediet kan het compacter, maar het budget wil ik altijd zien. Daar zit de kern van verantwoord lenen.`}
  ]},
 {id:'vbj-094',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-01T17:30:00',views:483,tags:['nieuw krediet','voorlichting','aanvraag'],beste:'vbj-094-a1',
  titel:'Kredietaanvraag door klant zelf tijdens het hypotheektraject',
  body:`Een klant heeft tijdens het hypotheektraject zelf online een lening aangevraagd voor de inrichting. Hij dacht dat het geen kwaad kon. Hoe groot is de impact?`,
  antwoorden:[
   {id:'vbj-094-a1',auteur:'u1',datum:'2026-09-02T11:03:00',rA:{},rAdv:{u2:3,u3:4,u6:3,u7:5},body:`Een nieuwe lening verandert de toets en moet worden gemeld bij de geldverstrekker. Afhankelijk van de hoogte kan het de financiering in gevaar brengen.
- Vraag het contract en een actueel overzicht op.
- Meld het bij de geldverstrekker.
- Bespreek of de lening kan worden ontbonden.
Leg vast wanneer de klant het meldde en wat je hebt gedaan.`},
   {id:'vbj-094-a2',auteur:'u4',datum:'2026-09-03T04:08:00',rA:{},rAdv:{u3:5},body:`Bij een consumptief krediet heeft de klant meestal een bedenktijd na het afsluiten. Als die nog loopt, is ontbinden een snelle oplossing. Controleer de voorwaarden van de kredietverstrekker.`}
  ]},
 {id:'vbj-095',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-07T19:05:00',views:6,tags:['webwinkel','krediet','BKR'],beste:'vbj-095-a1',
  titel:'Krediet via een webwinkel voor een witgoedaankoop',
  body:`Een klant heeft een wasmachine gekocht met gespreide betaling via een webwinkel. Hij weet niet of het een krediet is. Hoe zoek ik dat uit?`,
  antwoorden:[
   {id:'vbj-095-a1',auteur:'u4',datum:'2026-09-08T08:39:00',rA:{u6:5},rAdv:{u6:4,u7:4,u8:5},body:`Kijk naar het contract of de bevestiging. Bij een kredietovereenkomst met een kredietverstrekker staat het in de regel op het BKR-overzicht. Bij korte gespreide betaling zonder rente is dat niet altijd zo.
- Vraag de klant om de bevestiging.
- Kijk op het BKR-overzicht.
- Neem de lasten mee in het budget.`}
  ]},
 {id:'vbj-096',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-10T11:25:00',views:146,tags:['zzp','BKR','zakelijk krediet'],beste:null,
  titel:'Zelfstandige met registratie van een zakelijk krediet op privénaam',
  body:`Een zzp-klant heeft voor zijn bedrijf een krediet op privénaam afgesloten. Op het BKR-overzicht staat het als consumptief krediet. Hoe gaan geldverstrekkers ermee om?`,
  antwoorden:[
   {id:'vbj-096-a1',auteur:'u5',datum:'2026-09-10T13:14:00',rA:{u1:4,u2:5,u6:3,u8:5},rAdv:{u1:5},body:`Een krediet dat op privénaam staat, telt in de toets mee als privékrediet, ook als het geld in de onderneming is gestoken. De rente kan wel in de winst verwerkt zijn, maar de last blijft privé.
- Vraag het contract op.
- Kijk naar de jaarstukken.
- Leg vast hoe je het hebt meegenomen.
Bespreek met de klant of het krediet zakelijk kan worden ondergebracht.`}
  ]},
 {id:'vbj-097',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-13T08:15:00',views:476,tags:['klacht','BKR','afwijzing'],beste:'vbj-097-a1',
  titel:'Klacht van klant over afwijzing vanwege BKR',
  body:`Een klant is boos omdat zijn aanvraag is afgewezen vanwege een oude registratie. Hij vindt dat ik dat had moeten voorzien. Hoe gaan jullie om met zo'n klacht?`,
  antwoorden:[
   {id:'vbj-097-a1',auteur:'u8',datum:'2026-09-13T22:37:00',rA:{u2:5,u6:3,u7:5},rAdv:{u2:3,u7:4},body:`Behandel de klacht volgens de klachtenprocedure van je kantoor. Kijk in het dossier wat er is vastgelegd over de BKR-toetsing en wat je de klant hebt verteld.
- Reageer schriftelijk en tijdig.
- Leg uit wat je hebt gedaan en waarom.
- Kijk of er lessen zijn voor je werkwijze.
Heb je de registratie vooraf besproken en vastgelegd, dan sta je sterk.`},
   {id:'vbj-097-a2',auteur:'u4',datum:'2026-09-14T12:52:00',rA:{},rAdv:{u5:5},body:`Ik zou de klant ook een vervolgstap bieden: welke geldverstrekker heeft wel ruimte, of wanneer kan het opnieuw. Dat kalmeert vaak meer dan een uitleg.`},
   {id:'vbj-097-a3',auteur:'u1',datum:'2026-09-14T16:45:00',rA:{u2:3,u5:3,u6:5,u8:5},rAdv:{u2:5,u6:5,u7:5},body:`En leg vooraf altijd schriftelijk vast dat acceptatie niet gegarandeerd is.`}
  ]},
 {id:'vbj-098',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-17T09:10:00',views:394,tags:['ouders','krediet','gezin'],beste:null,
  titel:'Krediet van een minderjarig kind op naam van de ouders',
  body:`Ouders hebben een lening op hun naam voor de auto van hun kind. Het kind betaalt de maandlast. Telt die lening in de toets voor de ouders?`,
  antwoorden:[
   {id:'vbj-098-a1',auteur:'u4',datum:'2026-09-18T06:10:00',rA:{u5:5,u8:5},rAdv:{u5:5},body:`Ja, de lening telt mee. De ouders zijn de schuldenaar, de lening staat op hun naam bij BKR en de kredietverstrekker kan hen aanspreken. Dat het kind de maandlast betaalt, is een onderlinge afspraak die een geldverstrekker niet als vermindering van de last ziet.
Opties:
- De lening aflossen voor de aanvraag.
- Als het kind meerderjarig wordt, kan het een eigen lening afsluiten om die van de ouders af te lossen, met een eigen toetsing.
- De lening laten staan en met de lagere leenruimte werken.
Leg in het dossier vast hoe de lening in de toetsing is meegenomen en welke opties je hebt besproken. Bespreek ook met de ouders wat het betekent als het kind de betalingen niet meer doet.`}
  ]},
 {id:'vbj-099',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-19T17:00:00',views:258,tags:['doorlopend krediet','berekening','uitleg'],beste:'vbj-099-a1',
  titel:'Hoe reken je het effect van een doorlopend krediet uit voor de klant?',
  body:`Ik wil de klant laten zien hoeveel minder hypotheek hij kan krijgen door zijn doorlopend krediet. Hoe rekenen jullie dat voor?`,
  antwoorden:[
   {id:'vbj-099-a1',auteur:'u1',datum:'2026-09-20T09:19:00',rA:{u3:4,u8:3},rAdv:{u7:5},body:`Ik gebruik het adviespakket voor een berekening met en zonder het krediet. In de toets telt een maandlast op basis van de limiet volgens de actuele normen. Die maandlast verlaagt de ruimte voor de hypotheeklasten.
- Laat beide uitkomsten naast elkaar zien.
- Leg uit dat het om de limiet gaat, niet het saldo.
- Leg de vergelijking vast in het dossier.`},
   {id:'vbj-099-a2',auteur:'u6',datum:'2026-09-20T22:10:00',rA:{u8:4},rAdv:{u1:4},body:`In het adviespakket kun je de verplichting aan- en uitzetten in een variant. Zo hoef je de gegevens niet twee keer in te voeren.`}
  ]},
 {id:'vbj-100',cat:'kred',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-23T14:40:00',views:374,tags:['BKR','misverstand','voorlichting'],beste:null,
  titel:'BKR-registratie en het verkrijgen van een huurwoning of energiecontract',
  body:`Een klant met een registratie vraagt of hij hierdoor ook geen huurwoning of energiecontract kan krijgen. Wat kan ik hem vertellen?`,
  antwoorden:[
   {id:'vbj-100-a1',auteur:'u2',datum:'2026-09-24T16:30:00',rA:{u3:3,u6:4},rAdv:{u5:4},body:`BKR-gegevens zijn bedoeld voor kredietverstrekkers en zijn niet zomaar toegankelijk voor verhuurders of energieleveranciers. Die kunnen wel eigen controles doen, bijvoorbeeld met een inkomenstoets of eigen betalingsgegevens.
- Leg uit wie toegang heeft tot BKR-gegevens.
- Verwijs bij specifieke vragen naar de informatie van BKR zelf.
- Leg vast wat je hebt besproken.`}
  ]}
]);
